'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>{const ref=({'ought to':'ought','oughtto':'ought','out of':'out','out of work':'work','out-of-date':'date','outfits':'outfit'})[w]||w.toLowerCase().replaceAll(' ','-');return {origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+ref};};
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('orphanage','Orphanage is orphan + -age; it first named the state of being an orphan and later a home for orphaned children.',C('orphanage.s1','孤儿院','The county converted an empty school into an orphanage where children could live while relatives were being found.','县里把一所空校舍改成孤儿院，让孩子们在寻找亲属期间有地方居住。','The county converted an empty school / into an orphanage / where children could live while relatives were being found.','orphanage 指收容和照料孤儿的机构或住所。','孩子们在寻找亲属期间住在这所机构里。'),M('The county called the building an orphanage, but it provided no housing or care for orphaned children.','The county called the building an orphanage because it housed and cared for orphaned children.','没有收容或照料孤儿的建筑不符合 orphanage 的机构义。','meaning'),[q('Where did the children stay while relatives were being found?','in the converted school','in the county court','on a fish-hawk nesting platform','孩子们住在改建后的孤儿院里。'),q('What is an orphanage in this entry?','a home that cares for orphaned children','a school for training county judges','a bird shelter beside a lake','orphanage 是照料孤儿的住所。',1,'meaning'),q('Why was the empty school converted?','to give children a place to live','to display orthographic rules','to treat a broken bone','改建是为了给孩子提供住处。',1,'context'),q('Which word part was added to orphan to form orphanage?','-age','-ology','-ize','该词由 orphan 加 -age 构成。',1,'word-formation')]);
P('orthodox','Orthodox came through Late Latin from Greek orthodoxos, “having the right opinion,” from orthos “right” and doxa “opinion.”',[C('orthodox.s1','正统的；传统的','The museum describes the orthodox account of the ceremony, based on the version accepted by the community for generations.','博物馆介绍了这一仪式的正统说法，即社区世代认可的版本。','The museum describes the orthodox account / of the ceremony / based on the version accepted for generations.','orthodox 可表示遵循某群体长期接受的信仰或方法。','这套说法在该群体中被长期认可。'),C('orthodox.s2','东正教的','An Orthodox church with painted icons stands beside the old harbor in the coastal town.','海滨小镇的旧港旁有一座装饰着圣像的东正教教堂。','An Orthodox church / with painted icons / stands beside the old harbor.','首字母大写的 Orthodox 可指东正教会及其成员。','教堂和圣像提示东正教语境。'),C('orthodox.s3','常规的；得到公认的','The team rejected the orthodox treatment and tested a new method after standard care failed.','常规治疗无效后，团队放弃了公认疗法，转而测试一种新方法。','The team rejected the orthodox treatment / and tested a new method / after standard care failed.','orthodox 也可指普遍认可或常规的做法。','新方法与既有常规治疗相对。')],M('The clinic followed the orthodox standard treatment but called it an entirely unaccepted and unprecedented method.','The clinic followed the orthodox standard treatment, which was widely accepted.','orthodox 意为符合正统或常规标准，与“完全不被接受”相矛盾。','meaning'),[q('Which account did the museum present?','the version accepted for generations','a brand-new treatment trial','a list of bird species','博物馆介绍的是社区世代认可的仪式说法。'),q('What identifies the church as Orthodox?','painted icons and its Orthodox affiliation','an experimental treatment protocol','a list of spelling variants','第二个义项指东正教会。',2,'context'),q('Why did the team reject the orthodox treatment?','standard care had failed','the ceremony was centuries old','the spelling system used icons','常规治疗无效后团队测试新方法。',3,'context'),q('Orthodox most nearly means “orthodox” in which phrase?','the generally accepted standard method','a secret method no one has approved','a fish-eating bird at a lake','orthodox 可表示公认或常规的。',1,'meaning')]);
P('orthodoxy','Orthodoxy came through French and Late Latin from Greek orthodoxia, “right opinion”; it means beliefs or practices accepted as correct.',C('orthodoxy.s1','正统学说','The historian compared the official orthodoxy with letters showing that some early members held different views.','历史学家把官方正统学说与信件作了比较，信件表明早期一些成员持有不同观点。','The historian compared the official orthodoxy / with letters showing / that early members held different views.','orthodoxy 指由传统或权威认可为正确的一套观念或做法。','官方学说与早期成员的其他观点形成对照。'),M('The council called the accepted doctrine orthodoxy, although it said nobody regarded the doctrine as correct or authoritative.','The council called the accepted doctrine orthodoxy because the tradition regarded it as correct.','orthodoxy 是被权威或传统接受为正确的学说，不是无人认可的意见。','meaning'),[q('What did the historian compare with the official orthodoxy?','letters documenting different early views','a new bone-treatment method','a fish hawk’s flight pattern','历史学家用信件与官方正统学说作比较。'),q('What is orthodoxy?','beliefs accepted as correct by a tradition or authority','any idea that has never been accepted','the spelling rules of one language only','它指被传统或权威认可为正确的观念。',1,'meaning'),q('What did the letters reveal?','some early members held different views','every early member agreed completely','the council treated a broken bone','信件显示早期成员中有人持不同观点。',1,'context'),q('Which pair best distinguishes the terms?','orthodox describes something; orthodoxy is the accepted doctrine','orthodox is a bird; orthodoxy is its nest','orthodox is a verb; orthodoxy is its past tense','orthodoxy 是被认可的学说，orthodox 是形容词。',1,'distinction')]);
P('orthography','Orthography comes from Greek orthographia, from orthos “correct” and graphein “write”; it refers to conventional spelling and writing rules.',C('orthography.s1','拼写体系','The teacher compared English orthography with the spelling rules used in the students’ first language.','老师把英语拼写体系与学生母语中的拼写规则作了比较。','The teacher compared English orthography / with the spelling rules / used in the students’ first language.','orthography 指一种语言约定俗成的书写和拼写方式。','比较对象是两种语言的拼写规则。'),M('The handbook explained English orthography by listing pronunciation recordings but giving no information about letters or spelling conventions.','The handbook explained English orthography by describing its letters and spelling conventions.','orthography 关注字母和拼写惯例，单列语音录音并不能说明拼写体系。','meaning'),[q('What did the teacher compare?','English spelling rules and those of the students’ first language','two methods of treating joint injuries','two species of fish-eating birds','比较的是两种语言的拼写规则。'),q('What does orthography cover?','conventional letters and spelling rules','only the meaning of spoken gestures','the treatment of bones and muscles','orthography 是书写字母和拼写规则的体系。',1,'meaning'),q('Which reference belongs in a study of orthography?','a guide to how words are conventionally spelled','a chart of a bird’s wing movements','a clinic’s list of surgical instruments','拼写指南说明语言的 orthography。',1,'context'),q('Which Greek element means “write” in orthography?','graphein','orthos','doxa','graphein 的意思是“写”。',1,'word-formation')]);
P('orthopedics','Orthopedics was formed from French orthopédie, built from Greek orthos “straight” and paidion “child”; it names treatment of the musculoskeletal system.',C('orthopedics.s1','骨科；矫形外科','After the skier fractured her ankle, the emergency doctor referred her to orthopedics for follow-up care.','滑雪者脚踝骨折后，急诊医生把她转到骨科继续治疗。','After the skier fractured her ankle / the emergency doctor referred her / to orthopedics for follow-up care.','orthopedics 是诊治骨骼、关节及肌肉系统问题的医学专科。','骨折后的后续治疗属于骨科。'),M('The patient visited orthopedics to have a fractured ankle treated, although orthopedics deals only with spelling and letter forms.','The patient visited orthopedics to have the fractured ankle treated.','orthopedics 诊治肌肉骨骼系统，并非研究拼写的语言学科。','distinction'),[q('Why was the skier referred to orthopedics?','she had fractured her ankle','she needed help with Greek spelling','she was studying fish-eating birds','脚踝骨折需要骨科跟进治疗。'),q('What does orthopedics treat?','problems of bones, joints, and the musculoskeletal system','conventional spelling rules','infections of the ear and throat only','骨科负责肌肉骨骼系统疾病。',1,'meaning'),q('Which patient most likely needs orthopedics?','a runner with a torn knee ligament','a student confused by English spelling','a patient with a hearing test appointment','膝韧带属于肌肉骨骼系统。',1,'context'),q('Orthopedics is a branch of?','medicine','linguistics','ornithology','orthopedics 是医学专科。',1,'meaning')]);
P('orthopteran','Orthopteran is built from Greek orthos “straight” and pteron “wing”; it names an insect of the order that includes grasshoppers and crickets.',C('orthopteran.s1','直翅目昆虫','A field guide identified the green cricket as an orthopteran from its leathery forewings and powerful hind legs.','野外指南根据这只绿色蟋蟀的革质前翅和有力后腿，将它鉴定为直翅目昆虫。','A field guide identified the green cricket / as an orthopteran / from its leathery forewings and powerful hind legs.','orthopteran 指包括蚱蜢和蟋蟀在内的一类昆虫。','蟋蟀及其翅膀特征支持该分类。'),M('The guide classified the cricket as an orthopteran because it was a mammal with fur and fed its young milk.','The guide classified the cricket as an orthopteran because it was an insect with characteristic forewings.','蟋蟀是昆虫，不是有毛并哺乳的哺乳动物。','distinction'),[q('Which insect did the guide identify?','a green cricket','a fish-eating hawk','an aquatic mammal','指南鉴定的是一只绿色蟋蟀。'),q('Which feature supported the orthopteran identification?','leathery forewings','dense waterproof fur','a spelling system with Greek letters','革质前翅是指南提到的昆虫特征。',1,'context'),q('Which animal is an orthopteran?','a grasshopper','an osprey','an otter','蚱蜢属于直翅目昆虫。',1,'meaning'),q('The name orthopteran combines Greek words for?','straight and wing','correct and opinion','ear and throat','词源组合表示“直”和“翅”。',1,'word-formation')]);
P('oscillate','Oscillate comes from Latin oscillare, “to swing”; it means to move back and forth or shift between views.',[C('oscillate.s1','摆动，振动','The needle began to oscillate around the centre mark as the instrument settled after the shock.','仪器受到震动后逐渐稳定，指针开始围绕中心刻度来回摆动。','The needle began to oscillate / around the centre mark / as the instrument settled after the shock.','oscillate 可表示物体反复在两个位置之间摆动。','指针围绕中心位置来回移动。'),C('oscillate.s2','犹豫，摇摆不定','Voters continued to oscillate between the two candidates because both offered similar plans.','由于两位候选人的计划相似，选民仍在两人之间摇摆不定。','Voters continued to oscillate between the two candidates / because both offered / similar plans.','oscillate 也可比喻在两种观点或选择之间不断变化。','选民在两个候选人之间难以决定。')],M('The needle oscillated steadily between the centre marks while remaining fixed at a single position.','The needle oscillated from side to side around the centre mark.','oscillate 指反复变换位置，不能同时说它固定在同一位置。','meaning'),[q('What moved around the centre mark?','the instrument’s needle','the voters’ polling station','the cricket’s forewings','摆动的是仪器指针。'),q('Between which choices did voters oscillate?','the two candidates','the two spelling systems','two kinds of joint treatment','选民在两位候选人之间犹豫。',2,'context'),q('Which sentence uses oscillate physically?','The pointer oscillates from side to side.','Her opinion oscillates between two plans.','The council rejected the orthodoxy.','第一句描述指针来回摆动。',1,'meaning'),q('In “oscillate between candidates,” the word means?','keep shifting between choices','swing a metal pointer','accept one view permanently','这里表示在选项之间不断摇摆。',2,'meaning')]);
P('oscillation','Oscillation comes from Latin oscillatio, from oscillare “to swing”; it names repeated back-and-forth movement or a repeated shift of state.',[C('oscillation.s1','振动，振荡','The sensor recorded a slow oscillation of the bridge deck as heavy trucks crossed it.','重型卡车驶过时，传感器记录到桥面缓慢的振动。','The sensor recorded a slow oscillation / of the bridge deck / as heavy trucks crossed it.','oscillation 可指物体往返移动形成的振动。','桥面在车辆经过时反复轻微移动。'),C('oscillation.s2','动摇，犹豫','The committee’s oscillation between expansion and closure delayed a decision for months.','委员会在扩建与关闭之间摇摆，导致决定拖延了好几个月。','The committee’s oscillation between expansion and closure / delayed a decision / for months.','oscillation 也可指观点或状态在不同选择间反复变化。','委员会长期在两个方案间摇摆。')],M('The bridge showed an oscillation, but the sensor confirmed that its deck never moved or changed position at all.','The bridge showed an oscillation as the deck moved repeatedly under the trucks.','振荡需要反复移动；“从未移动”与记录到的 oscillation 矛盾。','meaning'),[q('What did the sensor record?','the bridge deck’s slow movement','the committee’s final vote','an insect’s classification','传感器记录桥面缓慢振动。'),q('What choices caused the committee’s oscillation?','expansion and closure','orthography and orthodoxy','a clinic and an orphanage','委员会在扩建与关闭之间犹豫。',2,'context'),q('Which is a physical oscillation?','a bridge deck moving back and forth','a committee changing its preferred plan','a patient visiting orthopedics','桥面往复运动是物理振荡。',1,'meaning'),q('Oscillation in the committee example means?','repeated indecision between alternatives','a steady commitment to one plan','a measured spelling convention','这里指在不同方案间反复动摇。',2,'meaning')]);
P('osmosis','Osmosis was formed from Greek osmos, “a pushing”; it names water movement through a membrane and gradual absorption by exposure.',[C('osmosis.s1','渗透作用','Water moved into the saltier solution by osmosis through the membrane separating the two chambers.','水通过隔开两个容器的膜，以渗透作用进入盐度更高的溶液。','Water moved into the saltier solution by osmosis / through the membrane / separating the two chambers.','osmosis 指水分子通过半透膜向溶质浓度较高一侧移动。','膜两侧盐度不同，水向盐度较高一侧移动。'),C('osmosis.s2','潜移默化','Without formal lessons, the child learned the family’s expressions by osmosis from hearing them every day.','孩子没有上正式课程，却在每天听家人说话的过程中潜移默化地学会了那些表达。','Without formal lessons / the child learned the family’s expressions by osmosis / from hearing them every day.','osmosis 可比喻通过长期接触而逐渐吸收观念或知识。','孩子靠日常耳濡目染学会表达。')],M('The child learned the family expressions by osmosis after never hearing anyone use them and having no contact with the family.','The child learned the family expressions by osmosis from hearing relatives use them every day.','潜移默化的学习依赖持续接触；完全没有听过或接触就学会与语境矛盾。','meaning'),[q('Which side did water move toward in the experiment?','the saltier solution','the chamber with no membrane','the less salty side only','水通过膜进入盐度更高的一侧。'),q('How did the child learn the family’s expressions?','by hearing them every day','by measuring salt through a membrane','by attending a formal spelling class','孩子通过每天听家人说话潜移默化地学会表达。',2,'context'),q('Which example uses osmosis in biology?','water crossing a membrane toward a stronger solution','a child picking up phrases at home','a committee wavering between plans','第一项描述水通过膜的渗透作用。',1,'meaning'),q('“Learned by osmosis” most nearly means?','absorbed gradually through exposure','memorized in one formal lesson','written according to spelling rules','这里表示在长期接触中逐渐学会。',2,'meaning')]);
P('osprey','Osprey came through Old French osprai from Latin ossifraga, a name for a fish-eating bird; its deeper history is uncertain.',C('osprey.s1','鹗','An osprey hovered above the estuary, then plunged feet-first and rose with a fish in its talons.','一只鹗在河口上空盘旋，随后脚先入水，抓着一条鱼飞起。','An osprey hovered above the estuary / then plunged feet-first / and rose with a fish in its talons.','osprey 是捕食鱼类的鹰形鸟，常俯冲入水抓鱼。','脚先入水并用爪抓鱼是鹗的典型捕食方式。'),M('The osprey plunged into the estuary and returned with a fish in its talons, although the report identified it as a flightless grazing mammal.','The osprey plunged into the estuary and returned with a fish in its talons.','捕食鱼类并飞行的是鸟，不是不会飞的食草哺乳动物。','distinction'),[q('Where did the osprey hover?','above the estuary','inside an orthopedics clinic','over the committee room','鹗在河口上空盘旋。'),q('How did the bird catch its fish?','it plunged feet-first and grabbed it with its talons','it waited for the fish to fly into a tree','it absorbed the fish through osmosis','鹗脚先入水，用爪抓鱼。',1,'context'),q('Which animal is an osprey?','a fish-catching bird of prey','a semi-aquatic mammal with dense fur','a large flightless African bird','osprey 是捕食鱼类的鹰形鸟。',1,'meaning'),q('Which name history is stated cautiously?','it came through Old French from Latin; deeper roots are uncertain','it was invented from the English word “orthodox”','its name certainly means “river otter”','其拉丁语更深层词源存在不确定性。',1,'word-formation')]);
P('ostensible','Ostensible came from Latin ostensibilis, from ostendere, “to show”; it describes what appears or is stated to be true, whether genuine or not.',C('ostensible.s1','表面上的','The company’s ostensible reason for closing the branch was renovation, but internal emails pointed to falling sales.','公司表面上关闭分店的理由是翻修，但内部邮件显示真正原因是销售下滑。','The company’s ostensible reason / for closing the branch was renovation / but internal emails pointed to falling sales.','ostensible 表示声称或表面看来如此，不保证是真正原因。','邮件暗示翻修并非真正原因。'),M('The ostensible reason was the genuine and only cause, while the report said it was merely the reason presented to the public.','The ostensible reason was the reason presented publicly, though it may not have been the real cause.','ostensible 仅表示表面或声称的理由，不等于已确认的真实原因。','meaning'),[q('What reason did the company give publicly?','renovation','a new orthography course','an osprey nesting survey','公司公开给出的理由是翻修。'),q('What did the internal emails suggest?','falling sales were the real factor','the branch was being converted into an orphanage','the company had changed its spelling system','邮件显示销售下滑可能才是真正因素。',1,'context'),q('What does ostensible signal about a claim?','it appears or is stated to be so, but may not be genuine','it has been proved beyond doubt','it is an official spelling rule','ostensible 保留了真实性不确定的意味。',1,'meaning'),q('Which phrase best matches ostensible?','the ostensible purpose of the visit','the medically confirmed diagnosis','the final and undisputed cause','ostensible purpose 是表面上或声称的目的。',1,'meaning')]);
P('ostentation','Ostentation came through French from Latin ostentationem, “display”; it means showy behaviour intended to impress.',C('ostentation.s1','卖弄；虚饰','The gala’s ostentation was obvious in its gold-plated tables and a fountain flowing with sparkling wine.','晚会的铺张炫耀显而易见：镀金餐桌旁还有喷涌气泡酒的喷泉。','The gala’s ostentation was obvious / in its gold-plated tables / and sparkling-wine fountain.','ostentation 指刻意以铺张或炫耀给别人留下印象。','昂贵装饰和酒水喷泉是炫耀性的展示。'),M('The host avoided ostentation by using plain tables and refusing any display meant to impress the guests.','The host showed ostentation with gold-plated tables and extravagant decorations meant to impress guests.','朴素布置且拒绝炫耀，与 ostentation 的铺张展示义相反。','meaning'),[q('Which details showed ostentation at the gala?','gold-plated tables and a sparkling-wine fountain','a modest room with plain chairs','a committee’s spelling handbook','镀金桌和酒水喷泉体现铺张炫耀。'),q('What is the purpose of ostentation?','to impress others with a showy display','to hide all spending from public view','to explain a conventional spelling rule','它是意在给别人留下印象的炫耀行为。',1,'meaning'),q('Which event would most likely involve ostentation?','a lavish launch with a gold staircase and fireworks','a quiet repair meeting in a bare workshop','a routine eye examination','豪华发布会以昂贵装饰和烟火炫耀。',1,'context'),q('Ostentation is usually associated with?','showiness and display','humility and simplicity','uncertainty about a stated reason','该词指显摆和铺张。',1,'meaning')]);
P('ostracism','Ostracism comes from Greek ostrakismos, the practice of voting to exile someone using a potsherd ballot; it now means social exclusion.',C('ostracism.s1','排斥','After she reported the safety violation, the team’s ostracism left her out of meetings and group messages.','她举报安全违规后，团队排斥她，不再让她参加会议或加入群聊。','After she reported the safety violation / the team’s ostracism left her out / of meetings and group messages.','ostracism 指以拒绝交往或接纳作为惩罚的排斥行为。','她被排除在会议和群聊之外。'),M('The team showed ostracism by welcoming the reporter to every meeting, including her in every discussion, and inviting her to social events.','The team showed ostracism by excluding the reporter from meetings and social activities.','热情接纳并邀请参加活动并非 ostracism，排斥才符合词义。','meaning'),[q('Why did the team exclude the employee?','she reported a safety violation','she taught the team orthography','she examined the osprey','她举报了安全违规后遭到排斥。'),q('What is ostracism in the current sense?','deliberately excluding someone socially','formally spelling a word correctly','treating a bone fracture','ostracism 是拒绝接纳或交往的排斥。',1,'meaning'),q('Which action illustrates ostracism?','colleagues leave one person out of meetings as punishment','a committee invites every member to speak','a clinic refers a patient to orthopedics','把同事排除在会议之外是排斥行为。',1,'context'),q('What did the ancient Greek practice use as a ballot?','a potsherd','a bird feather','a medical chart','词源中的投票使用陶片。',1,'word-formation')]);
P('ostracize','Ostracize comes from Greek ostrakizein, “to banish by voting with potsherds”; today it means to exclude a person from a group.',C('ostracize.s1','排斥','The club voted not to ostracize the newcomer and instead invited him to help plan the next event.','俱乐部投票决定不排斥这位新成员，而是邀请他协助筹划下一场活动。','The club voted not to ostracize the newcomer / and instead invited him / to help plan the next event.','ostracize 是动词，指拒绝接纳某人或使其受群体排斥。','邀请新成员参与筹划说明俱乐部没有排斥他。'),M('The club ostracized the newcomer by inviting him into every group activity and asking him to lead the event.','The club ostracized the newcomer by excluding him from group activities and refusing to speak to him.','邀请参加活动并让其领导活动是接纳而非排斥。','meaning'),[q('What did the club decide about the newcomer?','not to ostracize him','to remove him from the town','to correct his orthography','俱乐部决定不排斥新成员。'),q('What did the club invite him to do?','help plan the next event','leave the group permanently','vote with an ancient potsherd','俱乐部邀请他协助筹划活动。',1,'context'),q('Which sentence uses ostracize correctly?','The group ostracized him and stopped inviting him.','The group ostracized him by welcoming him warmly.','The group ostracized the word by spelling it.','停止邀请他是排斥的表现。',1,'meaning'),q('Ostracize means to?','exclude someone from a community','display wealth to impress guests','move water across a membrane','ostracize 是把某人排斥在群体之外。',1,'meaning')]);
P('ostrich','Ostrich came through Old French from Latin struthio and Greek strouthion, names for the large bird; it is a large African bird that cannot fly.',C('ostrich.s1','鸵鸟','The ostrich covered the sandy plain in long strides, using its strong legs to outrun a jackal.','鸵鸟迈着大步穿过沙地，凭借强壮的腿跑赢了一只豺。','The ostrich crossed the sandy plain in long strides / using its strong legs / to outrun a jackal.','ostrich 指体型很大的非洲鸟类，不能飞行，但奔跑速度快。','强壮的长腿使它能快速奔跑。'),M('The ostrich lifted its wings and flew high over the plain to escape the jackal.','The ostrich ran across the plain on its powerful legs to escape the jackal.','鸵鸟不会飞，逃跑时靠强壮的腿奔跑。','distinction'),[q('How did the ostrich escape the jackal?','it ran quickly on its strong legs','it flew high over the plain','it swam through a membrane','鸵鸟靠强壮的腿快速奔跑。'),q('Where did the ostrich run?','across a sandy plain','through an eye clinic','along a spelling chart','鸵鸟跑过沙地。',1,'context'),q('Which statement about an ostrich is correct?','it is a large flightless African bird','it is a fish-catching hawk','it is a small aquatic mammal','鸵鸟是大型不会飞的非洲鸟。',1,'meaning'),q('What feature helped it outrun the jackal?','strong legs','a potsherd ballot','an outer membrane','强壮的腿让它跑得快。',1,'context')]);
P('other','Other comes from Old English ōther, from a Germanic word meaning “second or different”; it can mean additional, other people/things, or every second one.',[C('other.s1','别的；其他的；另外的','Please put the other folder beside the blue one; we need both for the meeting.','请把另一个文件夹放在蓝色文件夹旁边，开会时两个都要用。','Please put the other folder beside the blue one / we need both / for the meeting.','other 可作限定词，表示与已提到的不同或额外的一个。','the blue one 已提及，other 指另外的文件夹。'),C('other.s2','其他人；其他事物','Mina finished early, while the others stayed in the lab to calibrate the sensor.','米娜很早就完成了，其他人则留在实验室校准传感器。','Mina finished early / while the others stayed in the lab / to calibrate the sensor.','the others 可作代词，指其余的人或事物。','the others 指除米娜外的其他成员。'),C('other.s3','每隔……的','The shuttle leaves every other hour, so the next departure is at four o’clock.','接驳车每隔一小时发车，因此下一班是四点。','The shuttle leaves every other hour / so the next departure / is at four o’clock.','every other + 单数名词表示每隔一个，即每两个间隔一次。','班次在三点和四点之间间隔一小时。')],M('The shuttle leaves every other hours, and Mina took the others folder to the lab.','The shuttle leaves every other hour, and Mina took the other folder to the lab.','every other 后接单数名词；表示“另一个文件夹”时 other 修饰单数名词 folder。','grammar'),[q('Which folder should be placed by the blue one?','the other folder','the laboratory sensor','the next shuttle departure','要放在蓝色文件夹旁的是另一个文件夹。'),q('Who stayed in the lab?','the others','Mina alone','the shuttle driver only','the others 指米娜之外留下的人。',2,'context'),q('How often does the shuttle leave?','every two hours','every other hour','once each week','every other hour 表示每隔一个小时。',3,'context'),q('Which phrase uses other as a pronoun for remaining people?','the others stayed in the lab','the other folder is blue','every other hour','the others 可独立指其他人。',2,'meaning')]);
P('otherwise','Otherwise combines other + -wise and means “in another way,” “apart from that,” or “if not.”',[C('otherwise.s1','否则；不然','Wear a reflective vest after dark; otherwise, drivers may not see you beside the road.','天黑后要穿反光背心；否则，司机可能看不到路边的你。','Wear a reflective vest after dark / otherwise drivers may not see you / beside the road.','otherwise 可引出不遵守前项要求时可能发生的结果。','不穿反光背心会带来被司机看不到的风险。'),C('otherwise.s2','在其他方面；除此以外','The cabin is small but otherwise comfortable, with warm beds and a clean kitchen.','小屋虽小，但其他方面都很舒适，有温暖的床和干净的厨房。','The cabin is small / but otherwise comfortable / with warm beds and a clean kitchen.','otherwise 可表示除刚提到的方面之外。','除面积小之外，小屋舒适且设备齐全。'),C('otherwise.s3','以另外的方式；另行','If the standard test is unavailable, the lab must measure the sample otherwise.','如果无法进行标准检测，实验室就必须用其他方式测量样本。','If the standard test is unavailable / the lab must measure the sample otherwise.','otherwise 也可表示采用不同于已说明的方法。','无法使用标准测试时改用其他方法。')],M('Wear a reflective vest after dark; otherwise drivers will certainly see you even when you are hidden from view.','Wear a reflective vest after dark; otherwise drivers may not see you beside the road.','otherwise 引出不采取前项措施时的风险，错误句却说不穿背心也肯定看得见。','meaning'),[q('What might happen without a reflective vest?','drivers may not see the person','the cabin will become larger','the lab will close permanently','否则司机可能看不到路边的人。'),q('Apart from being small, how is the cabin described?','comfortable','unsafe and unusable','orthodox in its spelling','otherwise comfortable 表示其他方面舒适。',2,'context'),q('What should the lab do if the standard test is unavailable?','measure the sample by another method','stop measuring samples forever','send the sample to the cabin','otherwise 在这里表示另用一种方法。',3,'context'),q('In “wear a vest; otherwise, drivers may not see you,” otherwise means?','if you do not do that','in every other hour','in a comfortable way','这里 otherwise 表示“否则”。',1,'meaning')]);
P('otolaryngology','Otolaryngology combines Greek oto- “ear,” larynx “larynx,” and -logia “study”; it is the medical specialty for ear, nose, and throat disorders.',C('otolaryngology.s1','耳鼻喉科','Persistent hoarseness led the singer to make an appointment in otolaryngology for an examination of her throat.','持续声音嘶哑促使歌手预约耳鼻喉科，检查喉咙。','Persistent hoarseness led the singer / to make an appointment in otolaryngology / for a throat examination.','otolaryngology 是诊治耳、鼻、喉及相关结构疾病的医学专科。','喉咙症状属于耳鼻喉科诊治范围。'),M('The singer visited otolaryngology for a broken wrist, although the specialty deals with the ear, nose, throat, and related structures.','The singer visited otolaryngology for persistent hoarseness and a throat examination.','手腕骨折属于骨科范围，不是耳鼻喉科治疗对象。','distinction'),[q('Why did the singer book an appointment?','persistent hoarseness','a fractured wrist','a spelling dispute','歌手因持续声音嘶哑预约检查。'),q('Which areas does otolaryngology cover?','ear, nose, throat, and related structures','bones and joints only','spelling and written letters','该专科处理耳鼻喉及相关结构疾病。',1,'meaning'),q('Which symptom belongs in this specialty?','a persistent throat problem','a broken ankle','a damaged spelling chart','持续喉咙问题属于耳鼻喉科。',1,'context'),q('Which element in the word refers to the ear?','oto-','larynx','-logia','oto- 表示耳。',1,'word-formation')]);
P('otter','Otter comes from Old English otor, from an old Germanic animal-name; its deeper origin is uncertain.',C('otter.s1','水獭','The otter surfaced beside the riverbank with a mussel held between its front paws.','水獭在河岸边浮出水面，两只前爪之间夹着一只贻贝。','The otter surfaced beside the riverbank / with a mussel / held between its front paws.','otter 是有浓密毛皮、善游泳的半水生哺乳动物。','水獭在河里捕食并用前爪拿住食物。'),M('The otter surfaced beside the river with a mussel in its paws, although the guide identified it as a large flightless bird.','The otter surfaced beside the river with a mussel in its paws, and the guide identified it as a semi-aquatic mammal.','水獭是哺乳动物，不是不会飞的大型鸟类。','distinction'),[q('What did the otter hold in its paws?','a mussel','a Greek potsherd','a throat examination chart','水獭拿着一只贻贝。'),q('Where did it surface?','beside the riverbank','inside the spelling handbook','above the estuary in flight','水獭在河岸边浮出水面。',1,'context'),q('Which animal is an otter?','a semi-aquatic mammal with dense fur','a large flightless bird','a fish-catching hawk','otter 是半水生哺乳动物。',1,'meaning'),q('How certain is the deeper history of otter in this note?','it is left uncertain beyond the Old English and Germanic forms','it definitely comes from the Greek for “ear”','it was certainly named after a spelling rule','这里对更早词源明确保留不确定。',1,'word-formation')]);
P('ought','Ought developed from Old English āhte, historically related to owe; it became a modal verb expressing duty, advisability, or expectation.',C('ought.s1','应该','You ought to check the emergency exits before opening the building to visitors.','你应该在向访客开放大楼前检查紧急出口。','You ought to check the emergency exits / before opening the building / to visitors.','ought 表示义务或合理建议，固定结构为 ought to + 动词原形。','ought to 后接 check 这一动词原形。'),M('You ought check the emergency exits before opening the building to visitors.','You ought to check the emergency exits before opening the building to visitors.','情态动词 ought 后必须使用 ought to + 动词原形。','grammar'),[q('What should be checked before visitors enter?','the emergency exits','the otter’s paws','the spelling of a Greek ballot','开放前要检查紧急出口。'),q('Which structure is correct with ought?','ought to check','ought checking','ought checked','ought 后用 to 再接动词原形。',1,'grammar'),q('What does ought express in the example?','a sensible duty or recommendation','a past physical movement','a public display of wealth','这里表示应该履行的检查责任。',1,'meaning'),q('When should the exits be checked?','before the building opens to visitors','after every visitor has left','only if the exits are already locked','检查应在向访客开放前完成。',1,'context')]);
P('ought to','Ought to is the modal construction ought + to-infinitive, used for duty, sensible advice, or expected likelihood.',C('ought to.s1','应该','You ought to label the sample bottles before placing them in the shared refrigerator.','你应该先给样品瓶贴好标签，再放进公用冰箱。','You ought to label the sample bottles / before placing them / in the shared refrigerator.','ought to 后接动词原形，可表达责任、建议或预期。','label 是 to 后面的动词原形。'),M('You ought to labels the sample bottles before placing them in the refrigerator.','You ought to label the sample bottles before placing them in the refrigerator.','ought to 后必须使用动词原形，不能加第三人称单数词尾。','grammar'),[q('What should be labelled?','the sample bottles','the shared refrigerator’s shelves only','the committee’s ballot papers','应该先给样品瓶贴标签。'),q('Which verb form follows ought to?','label','labels','labelled','ought to 后接动词原形 label。',1,'grammar'),q('When should the bottles be labelled?','before going into the shared refrigerator','after the samples have been discarded','only when the refrigerator is unplugged','贴标签应在放入公用冰箱之前。',1,'context'),q('Ought to can express?','a duty, advice, or expectation','only a past event','a type of weight measurement','该结构可表示义务、建议或预期。',1,'meaning')]);
P('oughtto','Oughtto records the modal phrase ought to with its words fused in this headword; ought descends from Old English āhte, and the phrase expresses duty, probability, or an unfulfilled past duty.',[C('oughtto.s1','应该（义务、正确）','You oughtto return the borrowed field key to the ranger before sunset.','你应该在日落前把借来的野外钥匙还给护林员。','You oughtto return the borrowed field key / to the ranger / before sunset.','oughtto 的义务义相当于 ought to，后接动词原形。','按时归还钥匙是应尽之事。'),C('oughtto.s2','应当；想必（推测）','The ferry oughtto reach the island by noon if the crossing remains calm.','如果航程平稳，渡船想必会在中午前抵达岛上。','The ferry oughtto reach the island / by noon / if the crossing remains calm.','oughtto 可表示基于情况的预期或可能性。','平稳航行使中午前抵达成为合理预期。'),C('oughtto.s3','本应该（未做）','They oughtto have booked the return trip earlier, but every seat was already sold.','他们本应该早点预订返程票，但座位早已售罄。','They oughtto have booked the return trip earlier / but every seat / was already sold.','oughtto have + 过去分词可表示过去有责任做却没有做。','票已售罄，说明预订没有及时完成。')],M('They oughtto have booked the return trip earlier, and they did book it early before any seats sold.','They oughtto have booked the return trip earlier, but they waited until every seat sold out.','oughtto have booked 在此表示本应做却未做，不能再说他们已经提前订好了。','meaning'),[q('What should they return before sunset?','the borrowed field key','the ferry itself','the orthography handbook','他们应在日落前归还野外钥匙。'),q('What is expected if the crossing stays calm?','the ferry should reach the island by noon','every ferry seat will disappear before dawn','the ranger will close the clinic','平稳时预计渡船中午前抵达。',2,'context'),q('What does “oughtto have booked” imply in the final example?','they failed to book earlier, though they should have','they booked early and all seats remained empty','they must book a new field key','该过去结构表示本应早点订票但没有做到。',3,'meaning'),q('Which use expresses probability rather than duty?','The ferry oughtto arrive by noon.','You oughtto return the key.','They oughtto have booked yesterday.','第一句表示预计抵达。',2,'meaning')]);
P('ounce','Ounce came through Old French unce from Latin uncia, “a twelfth part”; it is a weight unit and can mean a very small amount.',[C('ounce.s1','盎司','The recipe calls for eight ounces of flour, which the baker weighed before mixing the dough.','食谱需要八盎司面粉，面包师在和面前称好了重量。','The recipe calls for eight ounces of flour / which the baker weighed / before mixing the dough.','ounce 是重量单位；一常衡盎司约为28克。','面粉被称重，体现重量单位义。'),C('ounce.s2','少量；一点','Despite the criticism, the volunteer showed not an ounce of resentment toward the visitors.','尽管受到批评，这名志愿者对访客没有表现出一丝怨恨。','Despite the criticism / the volunteer showed not an ounce of resentment / toward the visitors.','ounce 可用于 not an ounce of 表示某种品质的极少量。','not an ounce 强调完全没有怨恨。')],M('The baker weighed eight ounces of flour, each ounce equal to sixteen pounds.','The baker weighed eight ounces of flour, each ounce equal to one sixteenth of a pound.','一盎司是磅的十六分之一，不是十六磅。','measurement'),[q('How much flour did the recipe require?','eight ounces','eight pounds per ounce','one gram in total','食谱需要八盎司面粉。'),q('What did the volunteer show no ounce of?','resentment','flour','interest in spelling rules','志愿者没有表现出一丝怨恨。',2,'context'),q('About how much is one avoirdupois ounce?','one sixteenth of a pound','sixteen pounds','one twelfth of a kilogram','常衡盎司约为磅的十六分之一。',1,'measurement'),q('In “not an ounce of resentment,” ounce means?','a tiny amount','a precise weight on a scale','a dozen units','这里是“一点点”的比喻用法。',2,'meaning')]);
P('our','Our comes from Old English ūre, the genitive form of we; it is a possessive determiner for the speaker and others.',[C('our.s1','我们的','We put our field notebooks in a waterproof case before crossing the marsh.','我们穿过沼泽前，把野外笔记本放进防水箱里。','We put our field notebooks / in a waterproof case / before crossing the marsh.','our 是限定词，放在名词前表示属于说话者及其同伴。','our 修饰 notebooks，后接名词。'),C('our.s2','我国的；我方的；本公司的','Our team will represent the city at the regional rowing final next month.','我们队下个月将代表本市参加地区赛艇决赛。','Our team will represent the city / at the regional rowing final / next month.','our 也可由群体用来指自己所属的团队、组织或国家。','Our team 指说话者所在的队伍。')],M('Ours notebooks were locked away before our team left the marsh.','Our notebooks were locked away before our team left the marsh.','our 是名词前的限定词；名词性物主代词 ours 不能直接修饰 notebooks。','grammar'),[q('What did the group put in the waterproof case?','their field notebooks','a set of ferry tickets','an orthopedics chart','他们把野外笔记本装进防水箱。'),q('Which team will represent the city?','the speaker’s team','the opposing team only','the marsh ranger’s family','our team 指说话者所属的队伍。',2,'context'),q('Which phrase uses our correctly before a noun?','our field notebooks','ours field notebooks','we field notebooks','our 是限定词，应放在名词前。',1,'grammar'),q('Our most directly refers to?','belonging to the speaker and at least one other person','belonging only to the listener','a quantity of flour','our 表示属于说话者及其同伴。',1,'meaning')]);
P('ours','Ours developed from the possessive form our with -s; it is a possessive pronoun that stands in place of our plus a noun.',[C('ours.s1','我们的（名词性）','Their canoe is at the landing, but the blue canoe is ours.','他们的独木舟停在登陆点，而蓝色的那艘是我们的。','Their canoe is at the landing / but the blue canoe is ours.','ours 独立作名词性物主代词，代替 our canoe。','ours 后不再接被拥有的名词。'),C('ours.s2','我们的人；我方人员','The final two runners are ours, so our club still has a chance to win the relay.','最后两名选手是我们队的，因此俱乐部仍有机会赢得接力赛。','The final two runners are ours / so our club still has a chance / to win the relay.','ours 有时可指属于我方的人或队员。','ours 指代表本队参赛的选手。')],M('The blue canoe is ours canoe, and the final runners are ours team members.','The blue canoe is ours, and the final runners are ours.','名词性物主代词 ours 后不能再接 canoe 或 team members。','grammar'),[q('Which canoe belongs to the speaker’s group?','the blue canoe','the canoe at the landing only','the orthopteran field guide','蓝色独木舟属于说话者一方。'),q('Who are the final two runners?','members of the speaker’s club','the rival club’s coach','spectators at the landing','ours 指最后两名己方选手。',2,'context'),q('Which sentence uses ours as a possessive pronoun?','That blue canoe is ours.','That is ours canoe.','Ours team won the relay.','ours 独立代替 our canoe。',1,'grammar'),q('Ours can replace which phrase?','our canoe','we canoe','our’s canoe','名词性 ours 代替 our + 名词。',1,'meaning')]);
P('ourselves','Ourselves combines our with selves; it is used reflexively, for emphasis, or in by ourselves meaning without help or company.',[C('ourselves.s1','我们自己（反身）','We reminded ourselves to photograph each sample before sealing the container.','我们提醒自己在封好容器前给每份样本拍照。','We reminded ourselves / to photograph each sample / before sealing the container.','ourselves 作反身代词，指动作的施事者也承受该动作。','提醒的对象就是 we 所指的人。'),C('ourselves.s2','我们亲自（强调）','We ourselves checked every label rather than asking the supplier to do the inspection.','我们亲自检查了每个标签，而没有让供应商来做检验。','We ourselves checked every label / rather than asking the supplier / to do the inspection.','ourselves 可用于强调是“我们亲自”完成动作。','ourselves 紧跟 we，用来强调执行者。'),C('ourselves.s3','独自；靠自己','The two hikers reached the cabin by ourselves after the guide turned back at the pass.','向导在山口折返后，我们两名徒步者独自到达了小屋。','The two hikers reached the cabin by ourselves / after the guide turned back / at the pass.','by ourselves 表示没有其他人陪同或帮忙。','向导折返，徒步者剩下两人自行前往。')],M('We reminded ourselves to photograph each sample, but the sentence said the supplier reminded we.','We reminded ourselves to photograph each sample.','动词的受事与 we 指同一群人时，应使用反身代词 ourselves。','grammar'),[q('Who was reminded to photograph each sample?','the same people who gave the reminder','the supplier alone','the opposing runners','we 和 ourselves 指同一群人。'),q('Who checked every label personally?','we ourselves','the supplier alone','the hikers’ guide','ourselves 强调检查是由我们亲自完成。',2,'context'),q('What does “by ourselves” mean here?','without the guide’s company or help','with the supplier checking each item','as a reflexive object only','by ourselves 表示独自或没有他人帮助。',3,'meaning'),q('Which form is correct after “reminded”?','ourselves','ourselfs','we','复数主语 we 对应反身代词 ourselves。',1,'grammar')]);
P('oust','Oust came through Anglo-French ouster, “to remove,” and now means to force someone out of a position or place.',C('oust.s1','驱逐；罢免','The board voted to oust its chair after an independent review found repeated conflicts of interest.','独立审查发现主席屡次存在利益冲突后，董事会投票罢免了他。','The board voted to oust its chair / after an independent review found / repeated conflicts of interest.','oust 表示强行使某人离开职位或群体。','董事会投票迫使主席离职。'),M('The board voted to oust its chair by promoting him to the same office for another full term.','The board voted to oust its chair by removing him from office.','让主席继续留任并连任与罢免其职位相反。','meaning'),[q('Who did the board vote to oust?','its chair','the independent reviewer','the opposing team’s coach','董事会投票罢免主席。'),q('What led to the vote?','repeated conflicts of interest','a new orthography textbook','a shortage of ounces of flour','审查发现多次利益冲突后董事会投票。',1,'context'),q('Which action means to oust a leader?','force the leader out of office','invite the leader to another meeting','give the leader a longer term','oust 指迫使其离开职位。',1,'meaning'),q('Oust is closest in meaning to?','remove from a position','show off wealth','move back and forth','oust 意为驱逐或罢免。',1,'meaning')]);
P('ouster','Ouster is formed from oust with the action noun suffix -er; it means the forced removal of a person from office or a group.',C('ouster.s1','罢黜；撵走','The manager’s ouster followed an investigation into missing funds at the regional office.','地区办公室失款事件经过调查后，经理被罢免。','The manager’s ouster followed an investigation / into missing funds / at the regional office.','ouster 指把某人从职位、住所或群体中强行赶走的行为。','调查之后经理被迫离职。'),M('The manager’s ouster meant she was promoted to the same post and remained in charge without interruption.','The manager’s ouster meant she was forced to leave her post after the investigation.','ouster 是被迫离开职位，不是晋升并继续任职。','meaning'),[q('What happened to the manager?','she was forced from her position','she was elected to a higher office','she moved the office to another building','调查后经理被罢免。'),q('What prompted the ouster?','an investigation into missing funds','a successful orthopedics appointment','a relay race victory','失款调查导致经理被罢免。',1,'context'),q('Which noun names the act of forcing someone from office?','ouster','ostentation','oscillation','ouster 指罢免或赶走的行为。',1,'meaning'),q('What is the relation between ouster and oust?','ouster names the removal; oust is the verb','ouster is the person who performs surgery','oust is the past tense of ounce','ouster 是行为名词，oust 是动词。',1,'word-formation')]);
P('out','Out comes from Old English ūt, “outside”; it can mean outward, absent, extinguished or unavailable, public, or to reveal someone’s secret identity.',[C('out.s1','向外；在外面','The dog ran out through the open gate and stopped beside the garden wall.','狗从敞开的门跑出去，在花园墙边停下。','The dog ran out through the open gate / and stopped / beside the garden wall.','out 可表示从里面向外移动或位于外面。','狗从门内跑到了外面。'),C('out.s2','外出；不在家','I called twice, but the receptionist said the doctor was out until late afternoon.','我打了两次电话，但接待员说医生要到下午晚些时候才回来。','I called twice / but the receptionist said the doctor was out / until late afternoon.','人 be out 可表示外出、不在通常所在地点。','医生暂时不在办公室。'),C('out.s3','熄灭；用完','The lantern went out when the last drop of fuel left its small tank.','最后一滴燃料从小油箱用完时，提灯熄灭了。','The lantern went out / when the last drop of fuel / left its small tank.','灯火 go out 表示熄灭；资源也可表示用尽。','燃料用尽后灯火熄灭。'),C('out.s4','公开；出版；泄露','The final report is out today, and journalists are already discussing its findings.','最终报告今天公布，记者们已经开始讨论其中的发现。','The final report is out today / and journalists are already discussing / its findings.','out 可表示出版、发布或公开可得。','报告已经正式发布。'),C('out.s5','揭露（秘密身份）','The actor asked the magazine not to out her colleague before he chose to speak publicly.','演员请求杂志不要在同事决定公开发言前擅自曝光他的隐私身份。','The actor asked the magazine not to out her colleague / before he chose / to speak publicly.','out 作动词可指未经同意揭露某人的秘密身份或隐私。','同事尚未准备公开，杂志不应擅自曝光。')],M('The lantern went out after the fuel ran out, but the campsite stayed brightly lit by that same extinguished lantern.','The lantern went out after the fuel ran out, so the campers switched on a backup light.','灯火熄灭后不能再由同一盏灯照亮营地。','meaning'),[q('Where did the dog run?','through the gate to the outside','into the sealed kennel','to the doctor’s office','狗从门里跑到外面。'),q('Why was the doctor out?','the doctor was away until later','the doctor’s report had been published','the lantern had run out of fuel','这里 out 表示医生外出不在。',2,'context'),q('What happened when the final fuel was gone?','the lantern went out','the report came out','the actor was outed','灯火因燃料用尽而熄灭。',3,'context'),q('What does the verb out mean in “out her colleague”?','reveal the colleague’s private identity','publish a report','move through a gate','这里是未经同意曝光隐私身份。',5,'meaning')]);
P('out of','Out of combines out with of and can mean moving from inside something or having none of a supply.',[C('out of.s1','从……里出来；离开','The otter slipped out of the reed bed and dived into the open channel.','水獭从芦苇丛里溜出来，潜入开阔水道。','The otter slipped out of the reed bed / and dived / into the open channel.','out of 可表示从某个空间内部向外移动。','水獭离开芦苇丛进入水道。'),C('out of.s2','用尽；没有','The rescue crew was out of clean water after supplying the stranded hikers overnight.','救援队为受困徒步者供水一夜后，干净饮用水已经用完。','The rescue crew was out of clean water / after supplying the stranded hikers / overnight.','be out of + 名词可表示某种物品或资源已用完。','救援队不再有干净水可用。')],M('The rescue crew was out of clean water but still had a full tank of unused drinking water.','The rescue crew was out of clean water and had to request another supply.','out of clean water 表示没有干净水，不能同时说仍有一整箱未用的饮用水。','meaning'),[q('Where did the otter come from?','the reed bed','the orthopedics clinic','the ferry cabin','水獭从芦苇丛中出来。'),q('What supply had the rescue crew used up?','clean water','field notebooks','medical spelling charts','救援队已经用完干净饮用水。',2,'context'),q('Which sentence uses out of to mean “leaving the inside”?','She walked out of the tent.','We are out of fuel.','The final report is out.','第一句表示从帐篷里走出来。',1,'meaning'),q('In “out of clean water,” out of means?','having none left','moving from inside a room','publishing a report','这里表示干净水已用尽。',2,'meaning')]);
P('out of work','Out of work combines out of with work and describes the state of having no paid job.',C('out of work.s1','失业的','After the factory closed, several experienced machinists were out of work for months.','工厂关闭后，几名经验丰富的机械师失业了好几个月。','After the factory closed / several experienced machinists were out of work / for months.','out of work 作表语，表示没有工作、处于失业状态。','工厂关闭后机械师暂时没有工作。'),M('The machinists were out of work, so they reported to their full-time factory jobs every morning.','The machinists were out of work after the factory closed and began looking for new jobs.','失业与每天去上全职班互相矛盾。','meaning'),[q('Why were the machinists out of work?','the factory had closed','the orthography class had ended','the shuttle ran every other hour','工厂关闭导致机械师失业。'),q('What does out of work mean?','without a paid job','working outside in the open air','finished with a task','out of work 指没有工作。',1,'meaning'),q('Which person is out of work?','a mechanic whose employer shut down and who has no job','a mechanic on a paid lunch break','a mechanic working an outdoor shift','失去工作且没有新职位的人处于失业状态。',1,'context'),q('Is “out of work” used as a single adjective phrase here?','Yes, it describes the machinists’ employment status.','No, it names a person who removes workers.','No, it means the factory is outdoors.','该短语作表语描述就业状态。',1,'grammar')]);
P('out-of-date','Out-of-date combines out of with date and means no longer current, fashionable, or valid.',C('out-of-date.s1','过时的','The museum replaced its out-of-date evacuation map because the western stairwell had been closed.','博物馆更换了过时的疏散地图，因为西侧楼梯已经封闭。','The museum replaced its out-of-date evacuation map / because the western stairwell / had been closed.','out-of-date 可指资料或物品因信息变化而不再适用。','地图没有反映楼梯关闭这一新情况。'),M('The museum kept the out-of-date evacuation map because it showed the newly opened western stairwell accurately.','The museum replaced the out-of-date map because it did not show that the western stairwell had closed.','过时的地图不能准确反映新变化；错误句把新旧信息说反了。','meaning'),[q('Why did the museum replace the map?','the western stairwell had closed','the map showed a new open stairwell','the museum had no visitors','旧地图没有显示西侧楼梯已关闭。'),q('What does out-of-date mean here?','no longer accurate or suitable for current use','recently checked and fully current','printed in an unusual spelling system','地图信息已经不再适用。',1,'meaning'),q('Which item is out-of-date?','a timetable listing a route that stopped last year','a timetable updated this morning','a map showing the current exits','已停运路线仍被列出的时刻表已经过时。',1,'context'),q('Which punctuation form is used in this headword?','hyphens connect out-of-date before a noun','it must always be written as three separate verbs','it is one capitalized proper name','作定语时此处用连字符连接。',1,'spelling')]);
P('outbound','Outbound combines out with bound, from the idea of being directed outward; it describes travel or traffic leaving a place.',C('outbound.s1','外向的；出站的','Passengers for the outbound train waited on Platform 2, while arriving travellers left through the opposite gate.','乘坐出站列车的旅客在2号站台等候，而到站旅客从另一侧出口离开。','Passengers for the outbound train waited on Platform 2 / while arriving travellers / left through the opposite gate.','outbound 表示从某地向外出发或离开。','列车将乘客从车站送往外地。'),M('The outbound train was travelling into the station to arrive, while the inbound service was leaving for the coast.','The outbound train was leaving the station for the coast, while the inbound service was arriving.','outbound 是离开某地的方向，与进站抵达的 inbound 相反。','distinction'),[q('Where did outbound passengers wait?','on Platform 2','at the airport arrival gate','inside an orthopedics clinic','出站列车乘客在2号站台等候。'),q('Which direction does an outbound service travel?','away from its starting place','toward the place it is entering','back and forth between two points only','outbound 表示向外离开。',1,'meaning'),q('Which passenger is on an outbound trip?','someone leaving the city by train','someone arriving in the city by train','someone staying at home','离开城市乘车的人属于 outbound 旅客。',1,'context'),q('Outbound contrasts most directly with?','inbound','out-of-date','ostensible','inbound 表示向内或到达方向。',1,'distinction')]);
P('outbreak','Outbreak combines out and break and refers to a sudden start of disease or fighting, or a brief eruption of trouble or emotion.',[C('outbreak.s1','（疾病、暴力）爆发','Health officials traced the measles outbreak to a crowded indoor event held before the school term.','卫生官员追查麻疹疫情，发现它与开学前的一场室内拥挤活动有关。','Health officials traced the measles outbreak / to a crowded indoor event / held before the school term.','outbreak 可指疾病或暴力突然在某地出现并扩散。','多名病例与同一场活动相关，构成疫情爆发。'),C('outbreak.s2','（情绪、争吵）突发','An outbreak of laughter interrupted the otherwise serious meeting when the projector showed the wrong slide.','投影仪放错幻灯片时，一阵笑声打断了原本严肃的会议。','An outbreak of laughter interrupted the otherwise serious meeting / when the projector / showed the wrong slide.','outbreak 也可指短暂而突然的情绪、争吵或麻烦爆发。','笑声突然出现并打断会议。')],M('The outbreak of measles involved one sudden case that never spread, while officials described a large spreading cluster.','The measles outbreak involved a sudden cluster of cases linked to the crowded event.','若确认只有单例且没有扩散，就不能描述为这场大规模疫情爆发。','meaning'),[q('What event was linked to the measles outbreak?','a crowded indoor gathering','a train leaving Platform 2','a meeting about spelling','卫生部门把病例与一场拥挤室内活动联系起来。'),q('What interrupted the serious meeting?','a sudden burst of laughter','a measles vaccination campaign','the outbound train announcement','投影放错时突然爆发笑声。',2,'context'),q('Which is an outbreak in the disease sense?','a sudden cluster of measles cases','one routine eye appointment','a gradual change in opinion','麻疹突然集中出现属于疾病爆发。',1,'meaning'),q('In “an outbreak of laughter,” outbreak means?','a sudden short eruption','a lasting lack of emotion','a planned train departure','这里指突然爆发的一阵笑声。',2,'meaning')]);
P('outbuilding','Outbuilding combines out and building; it is a separate smaller structure such as a shed, barn, or garage near a main building.',C('outbuilding.s1','外屋','The gardener stored the mower and bags of compost in an outbuilding behind the farmhouse.','园丁把割草机和几袋堆肥存放在农舍后面的一间外屋里。','The gardener stored the mower and bags of compost / in an outbuilding / behind the farmhouse.','outbuilding 指与主屋分开的棚屋、谷仓或车库等附属建筑。','它位于农舍后方，用来存放园艺工具。'),M('The gardener stored the mower in an outbuilding that was the farmhouse’s central living room inside the main house.','The gardener stored the mower in a separate outbuilding behind the farmhouse.','位于主屋内部的客厅不是独立的附属建筑。','meaning'),[q('What was stored in the outbuilding?','a mower and compost','a train timetable','a set of spelling rules','园丁把割草机和堆肥放进外屋。'),q('Where was the outbuilding?','behind the farmhouse','inside the main living room','at the train platform','外屋位于农舍后面。',1,'context'),q('Which structure could be an outbuilding?','a detached garden shed','the main house’s kitchen','a railway platform','独立的小棚屋属于外屋。',1,'meaning'),q('What distinguishes an outbuilding from a main building?','it stands apart as a smaller separate structure','it is the largest room inside the main house','it is always underground','外屋是从主建筑分开的附属建筑。',1,'meaning')]);
P('outburst','Outburst combines out and burst and means a sudden strong expression of feeling or activity.',C('outburst.s1','爆发；迸发','Her outburst of anger surprised the panel when the chair abruptly ended the discussion.','主席突然结束讨论时，她勃然大怒，让评审组感到意外。','Her outburst of anger surprised the panel / when the chair / abruptly ended the discussion.','outburst 指情绪或行为突然强烈地表现出来。','她的愤怒突然爆发。'),M('Her outburst of anger was a calm, gradual feeling that she never expressed or showed to anyone.','Her outburst of anger was a sudden, forceful reaction to the chair ending the discussion.','outburst 是突然而强烈的表达，不是平静、缓慢且从未表现出来的感受。','meaning'),[q('What triggered her outburst?','the chair abruptly ended the discussion','the panel opened a new outbuilding','the train left Platform 2','主席突然结束讨论引发她发怒。'),q('What does outburst describe?','a sudden strong display of feeling or activity','a slow private change never expressed','a building detached from a farmhouse','outburst 指突然强烈的表现。',1,'meaning'),q('Which is an outburst?','a sudden shout of anger during a meeting','a quiet opinion formed over years','a planned schedule for a train','会议中突然怒吼是情绪爆发。',1,'context'),q('The word combines which two parts?','out + burst','our + best','orthos + pteron','outburst 由 out 与 burst 组合。',1,'word-formation')]);
P('outcast','Outcast comes from the idea of being cast out; as a noun it is an excluded person, and as an adjective it means rejected.',[C('outcast.s1','被遗弃的人','After the village rejected his proposal, the former leader lived as an outcast on the edge of town.','村民否决了他的提议后，这位前领导人像被排斥者一样住在镇子边缘。','After the village rejected his proposal / the former leader lived as an outcast / on the edge of town.','outcast 作名词指被社区赶出或不受欢迎的人。','他被村庄排斥，住在镇边。'),C('outcast.s2','被逐的','The outcast family was barred from the association hall even though it had paid the annual fee.','尽管交了年费，这个被排斥的家庭仍被禁止进入协会大厅。','The outcast family was barred from the association hall / even though it had paid / the annual fee.','outcast 也可作形容词，描述遭群体拒绝、不接纳的状态。','家庭被禁止进入大厅，体现受排斥状态。')],M('The village treated him as an outcast by inviting him to lead every meeting and welcoming him into every group.','The village treated him as an outcast by excluding him from meetings and group activities.','让他主持会议并欢迎加入群体是接纳，不是排斥。','meaning'),[q('Where did the former leader live?','on the edge of town','inside the association hall','at the railway station','他被排斥后住在镇子边缘。'),q('Why was the family called outcast?','it was barred from the association hall','it had founded the association','it was elected to lead every meeting','家庭被禁止进入大厅，说明遭到排斥。',2,'context'),q('Which sentence uses outcast as a noun?','The outcast lived beyond the village.','The outcast family was barred from the hall.','The family felt otherwise comfortable.','第一句中 outcast 指被排斥的人。',1,'grammar'),q('Which sentence uses outcast as an adjective?','The outcast family was denied entry.','The outcast lived alone.','The leader cast a vote.','outcast 修饰 family，表示被逐的。',2,'grammar')]);
P('outcome','Outcome combines out and come, originally “that which comes out”; it means the resulting situation or the product of an action.',[C('outcome.s1','结果；结局','The outcome of the election remained uncertain until the final district finished counting its ballots.','直到最后一个选区完成计票，选举结果仍不确定。','The outcome of the election remained uncertain / until the final district / finished counting its ballots.','outcome 可指活动或事件结束时出现的情况或结局。','计票完成后才能确定选举结局。'),C('outcome.s2','成果；效果','The treatment’s positive outcome allowed the patient to return to swimming within six weeks.','治疗取得了良好效果，患者六周内便能重新游泳。','The treatment’s positive outcome allowed the patient / to return to swimming / within six weeks.','outcome 也可指计划、治疗或讨论产生的效果。','治疗结果使患者恢复游泳。')],M('The election outcome was unknown because counting had finished and every district had already reported a final result.','The election outcome was unknown because the final district had not finished counting.','若各区已完成计票并公布结果，选举结局就不再未知。','meaning'),[q('When would the election outcome become clear?','after the final district finished counting','before any ballots were cast','when the treatment ended','最后一个选区完成计票后才能确定结果。'),q('What did the positive treatment outcome allow?','the patient returned to swimming','the election district reopened','the patient became an outcast','良好疗效使患者恢复游泳。',2,'context'),q('Which word best completes “the ___ of the trial was unexpected”?','outcome','outbuilding','outbound','试验结束后出现的结果是 outcome。',1,'meaning'),q('In “the outcome of treatment,” outcome means?','the effect or result produced','the location where treatment began','the person who performed surgery','这里指治疗产生的效果。',2,'meaning')]);
P('outcrop','Outcrop is formed from out and crop, with crop meaning a projection; it is a rock mass exposed at the surface, or the verb for becoming exposed.',[C('outcrop.s1','露头','A pale limestone outcrop rose above the grass beside the hiking trail.','徒步小径旁，一块浅色石灰岩露头高出草地。','A pale limestone outcrop rose above the grass / beside the hiking trail.','outcrop 作名词指露出地表的岩石块或岩层。','岩石露出草地表面。'),C('outcrop.s2','露出地表','The granite layer begins to outcrop near the river where the soil becomes thin.','土层变薄的河边开始有花岗岩层露出地表。','The granite layer begins to outcrop near the river / where the soil / becomes thin.','outcrop 也可作动词，表示岩层显露到地面。','土层变薄处能看到岩层。')],M('A limestone outcrop rose above the grass but remained completely buried beneath several metres of soil.','A limestone outcrop rose above the grass where the rock was exposed at the surface.','露头指已经露出地表的岩石，不可能同时完全埋在厚土层之下。','meaning'),[q('What rose above the grass?','a limestone rock mass','a train leaving the station','a family barred from the hall','小径旁露出地表的是石灰岩。'),q('Where did the granite begin to outcrop?','near the river where soil was thin','beneath a deep layer of fresh soil','inside the medical clinic','土层变薄的河边出现花岗岩露头。',2,'context'),q('Which sentence uses outcrop as a verb?','The bedrock outcrops along the stream.','An outcrop stands beside the trail.','The report described the election outcome.','第一句中 outcrops 表示岩层露出。',2,'grammar'),q('An outcrop is?','rock exposed at the ground surface','a sudden emotional reaction','a detached farm building','outcrop 指露出地表的岩石。',1,'meaning')]);
P('outcry','Outcry combines out and cry; as a noun it is strong public protest, and as a verb it means to cry out loudly.',[C('outcry.s1','强烈抗议，哗然','The proposed closure of the only rural clinic caused a public outcry among residents.','关闭唯一一家乡村诊所的提议引发居民强烈抗议。','The proposed closure of the only rural clinic / caused a public outcry / among residents.','outcry 作名词指公众强烈表达愤怒或反对。','居民的公开抗议针对诊所关闭计划。'),C('outcry.s2','喊叫','The child outcried when the cold water splashed across his face.','冷水溅到脸上时，孩子大声喊叫起来。','The child outcried / when the cold water / splashed across his face.','outcry 也可作动词，表示大声喊叫。','孩子因冷水溅到脸上而喊出声。')],M('The closure caused an outcry, but every resident publicly praised the proposal and expressed no objection.','The closure caused an outcry, as residents publicly protested the loss of their clinic.','outcry 表示强烈反对，人人赞扬且无人反对与此冲突。','meaning'),[q('What proposal caused the public outcry?','closing the only rural clinic','building a new outbuilding','changing the orthography textbook','居民抗议关闭唯一的乡村诊所。'),q('What made the child outcry?','cold water splashed on his face','the election result was announced','a train travelled outbound','冷水溅到脸上使孩子大叫。',2,'context'),q('Which phrase uses outcry as a noun?','a public outcry against the closure','the child outcried loudly','the outbound train departed','第一项中 outcry 是公众抗议。',1,'grammar'),q('Which sentence uses outcry as a verb?','The child outcried in surprise.','The public outcry delayed the vote.','The outcry was reported in the news.','第一句中 outcried 是动词，表示大声喊叫。',2,'grammar')]);
P('outdated','Outdated combines out and dated; it can describe something no longer suitable or information that is no longer accurate.',[C('outdated.s1','过时的；陈旧的','The factory replaced its outdated ventilation fan with a quieter, energy-efficient model.','工厂用更安静、节能的型号替换了陈旧的通风机。','The factory replaced its outdated ventilation fan / with a quieter / energy-efficient model.','outdated 可指不再符合当前需要的设备或做法。','旧风机被新型号取代。'),C('outdated.s2','信息过时的；不再准确的','The website displayed an outdated ferry timetable that still listed a route cancelled last winter.','网站显示了一份过时的渡船时刻表，上面仍列着去年冬天取消的航线。','The website displayed an outdated ferry timetable / that still listed a route / cancelled last winter.','outdated 也指因事实变化而不再准确的信息。','时刻表保留了已取消航线。')],M('The website’s outdated timetable was fully current because it removed the route cancelled last winter.','The website’s outdated timetable was no longer accurate because it still listed the cancelled route.','已过时的信息不应被说成完全准确；原句还说明旧时刻表保留了取消航线。','meaning'),[q('What replaced the outdated fan?','a quieter energy-efficient model','a louder fan from the same year','an orthopedics table','工厂换上更安静节能的新风机。'),q('What made the ferry timetable outdated?','it still listed a route cancelled last winter','it included the next season’s new route','it was printed on a new website','它仍列出去年冬季取消的航线。',2,'context'),q('Which object is outdated because of changed facts?','a map that shows a bridge still open after it was demolished','a current list of open bridges','a new fan that meets today’s standards','桥梁已拆除但地图仍标开放，信息不再准确。',2,'meaning'),q('Which use refers to something no longer suitable?','outdated factory equipment','an outdated report with a wrong date','a recently updated timetable','第一项强调设备不再适用。',1,'meaning')]);
P('outdistance','Outdistance combines out and distance and means to leave a competitor far behind, especially in a race.',C('outdistance.s1','远远超过','The lead cyclist began to outdistance the rest of the field on the steep climb.','领骑自行车手在陡坡上开始把其他选手远远甩在后面。','The lead cyclist began to outdistance the rest of the field / on the steep climb.','outdistance 指在竞赛中把对手远远落下。','陡坡上领骑者与其他选手的距离不断拉大。'),M('The lead cyclist outdistanced the field by riding behind every rival and letting them finish first.','The lead cyclist outdistanced the field by pulling far ahead of the other riders.','让所有对手先到终点与把对手远远甩开相反。','meaning'),[q('Where did the lead cyclist pull ahead?','on the steep climb','inside the old outbuilding','at the ferry office','领骑者在陡坡上甩开对手。'),q('What does outdistance mean in a race?','leave competitors far behind','finish exactly level with every rival','withdraw from the event before starting','该动词表示远远超过竞争者。',1,'meaning'),q('Which competitor outdistances the others?','a runner who opens a large lead','a runner who trails the group','a runner who ties with one rival','拉开很大差距的选手远远领先。',1,'context'),q('The prefix out- in outdistance suggests?','surpassing another in degree or performance','moving into an enclosed space','being out of a supply','这里 out- 表示超过。',1,'word-formation')]);
P('outdo','Outdo combines out with do and means to perform better than another person.',C('outdo.s1','胜过；做得比……好','Both bakers tried to outdo each other, but the judges praised the originality of each cake.','两位面包师都想胜过对方，但评委称赞了每块蛋糕的独创性。','Both bakers tried to outdo each other / but the judges praised / the originality of each cake.','outdo 表示在表现或成就上超过别人。','两位烘焙师互相竞争，希望做得更好。'),M('The baker outdid her rival by submitting a cake that was worse in every respect and received the lowest score.','The baker outdid her rival by submitting a more original cake that earned a higher score.','各方面更差且得分最低表示落后，不是胜过对手。','meaning'),[q('What did the judges praise?','the originality of each cake','the outbuilding behind the bakery','the ferry timetable','评委称赞蛋糕的独创性。'),q('What does outdo mean?','do better than someone else','copy someone without improving','leave a job because it is outdated','outdo 指表现胜过别人。',1,'meaning'),q('Which action shows one chef outdoing another?','creating a dish that earns higher marks','serving the same dish at the same time','withdrawing before the contest begins','做出得分更高的菜表示胜过对手。',1,'context'),q('What is the past form of outdo?','outdid','outdone','outdoed','outdo 的过去式是不规则形式 outdid。',1,'grammar')]);
P('outdoor','Outdoor combines out and door; it describes activities done outside or equipment/clothing designed for outside use.',[C('outdoor.s1','户外的；室外的','The school cancelled its outdoor concert when lightning approached the open field.','雷电接近露天场地时，学校取消了户外音乐会。','The school cancelled its outdoor concert / when lightning approached / the open field.','outdoor 可描述在建筑物外举行或进行的活动。','音乐会原定在露天场地举行。'),C('outdoor.s2','户外套装的；适于室外的','For the winter trip, Mara packed outdoor clothing rated for rain, wind, and freezing temperatures.','冬季旅行时，玛拉带上了适合雨、风和冰冻天气的户外服装。','For the winter trip / Mara packed outdoor clothing / rated for rain, wind, and freezing temperatures.','outdoor 也可形容适合室外环境和天气的用品或服装。','服装按恶劣天气设计。')],M('The school held an outdoor concert inside a sealed hall with no access to outside air.','The school held an outdoor concert on the open field before lightning approached.','在密闭室内举行的活动不是 outdoor concert。','meaning'),[q('Why was the concert cancelled?','lightning approached the open field','the indoor hall had an outbuilding','the school ran out of spelling books','雷电接近露天场地后学校取消音乐会。'),q('What did Mara pack for the winter trip?','clothing designed for rain and freezing weather','light summer clothes for a heated hall','a ferry timetable from last winter','她带了适合恶劣天气的户外服装。',2,'context'),q('Which phrase means “held outside”?','an outdoor concert on the lawn','an outdoor coat rated for rain','a concert inside a hall','第一项中 outdoor 描述在室外举行。',1,'meaning'),q('Which item is outdoor gear?','a waterproof jacket for hiking in wind and rain','a silk shirt intended only for a warm ballroom','a paper timetable for a train','适合雨天徒步的防水衣是户外用品。',2,'meaning')]);
P('outdoors','Outdoors combines out and doors and functions as an adverb or noun meaning in the open air, away from buildings.',C('outdoors.s1','户外；在户外','The children ate lunch outdoors under a broad maple tree because the classroom was being painted.','教室正在粉刷，孩子们便在一棵大枫树下户外用午餐。','The children ate lunch outdoors / under a broad maple tree / because the classroom was being painted.','outdoors 表示在建筑物外的露天空地。','午餐地点是在树下的户外。'),M('The children ate lunch outdoors in a locked classroom with no windows or access to the open air.','The children ate lunch outdoors beneath the maple tree outside the classroom.','锁着的教室内部不是户外环境。','meaning'),[q('Where did the children eat lunch?','under a maple tree','inside the locked classroom','at the ferry terminal','孩子们在枫树下吃午餐。'),q('Why did they eat outdoors?','the classroom was being painted','the weather was freezing indoors','the school had no maple tree','教室粉刷期间，孩子们到室外用餐。',1,'context'),q('Which sentence uses outdoors as an adverb?','We spent the afternoon outdoors.','The outdoors is beautiful in spring.','She bought outdoor clothing.','第一句中 outdoors 修饰 spent，表示在户外。',1,'grammar'),q('Outdoors most nearly means?','in the open air','inside a building','at a distant edge','outdoors 指在露天空气中。',1,'meaning')]);
P('outer','Outer combines out with the comparative suffix -er; it means farther from the centre or concerned with outward appearance.',[C('outer.s1','外部的；外围的','The outer wall of the ancient fort was built farther from the central courtyard than the inner wall.','古堡的外墙比内墙离中央庭院更远。','The outer wall of the ancient fort / was built farther from / the central courtyard.','outer 可表示位于中心之外或较靠近外层。','墙在中央庭院之外。'),C('outer.s2','外表的；表面的','His calm outer manner concealed the worry he felt about the medical results.','他平静的外在举止掩盖了对检查结果的担忧。','His calm outer manner / concealed the worry / he felt about the medical results.','outer 也可指外在表现，与内心感受相对。','平静的表面表现与内在担忧不同。')],M('The outer wall stood closest to the central courtyard, while the inner wall formed the distant perimeter.','The outer wall stood farther from the central courtyard, around the fort’s perimeter.','外墙应位于更外围，不会比内墙更靠近中心庭院。','meaning'),[q('Where was the fort’s outer wall?','farther from the central courtyard','inside the central courtyard','below the deepest foundation','外墙处在中央庭院之外。'),q('What did his outer manner conceal?','worry about the medical results','an outdated ferry route','a broken wall','平静的外在举止掩盖内心担忧。',2,'context'),q('Which phrase uses outer for location?','the outer wall around the fort','her outer appearance hid fear','the outermost island in the chain','第一项指位于外围的墙。',1,'meaning'),q('Which phrase uses outer in contrast with inner feelings?','his outer calm','the outer wall','the outer edge of the map','outer calm 表示外在表现出的平静。',2,'meaning')]);
P('outermost','Outermost combines outer and -most and means farthest from the centre or boundary.',C('outermost.s1','最外面的；最远的','The outermost marker on the reef lies farthest from shore and is visible only at low tide.','礁石最外侧的标记离岸最远，只有退潮时才看得见。','The outermost marker on the reef / lies farthest from shore / and is visible only at low tide.','outermost 表示在一组物体中最靠外或离中心最远。','该标记是距海岸最远的那个。'),M('The outermost marker was the one nearest the shore, while every other marker lay farther out.','The outermost marker was the farthest one from shore.','outermost 表示最外侧或最远处，不能指最靠近岸边的标记。','meaning'),[q('When was the outermost reef marker visible?','at low tide','only at high tide','after the reef was moved inland','退潮时最外侧标记才看得见。'),q('Which marker is outermost?','the one farthest from shore','the one nearest the beach','the one in the central courtyard','outermost 指最远离海岸的标记。',1,'context'),q('Which object is outermost in a set of rings?','the ring farthest from the centre','the ring at the very centre','a ring hidden inside a box','离中心最远的环位于最外侧。',1,'meaning'),q('What does the suffix -most add to outer?','the greatest degree or farthest position','a past action','a person who performs an action','-most 表示最高程度或最远位置。',1,'word-formation')]);
P('outfit','Outfit combines out and fit; it can mean a set of clothes, an organized group, or to equip someone.',[C('outfit.s1','全套服装','Nora chose a practical outfit of wool trousers, a warm sweater, and waterproof boots.','诺拉选了一套实用服装，包括羊毛裤、保暖毛衣和防水靴。','Nora chose a practical outfit / of wool trousers, a warm sweater, / and waterproof boots.','outfit 作名词可指为某场合搭配的一整套衣服。','裤子、毛衣和靴子组成一套服装。'),C('outfit.s2','团队；班子；机构','A small survey outfit mapped the marsh before the new road was approved.','一支小型勘测团队在新道路获批前绘制了沼泽地图。','A small survey outfit mapped the marsh / before the new road / was approved.','outfit 也可指共同工作的组织或团队。','该团队负责湿地测绘。'),C('outfit.s3','装备；供给服装用具','The guide outfitted each hiker with a helmet, a headlamp, and a radio.','向导为每位徒步者配备了头盔、头灯和对讲机。','The guide outfitted each hiker / with a helmet, a headlamp, / and a radio.','outfit 作动词表示为某人提供所需服装或装备。','向导给每位徒步者配齐装备。')],M('The guide outfitted each hiker by taking away every helmet, lamp, and radio they needed.','The guide outfitted each hiker with the helmet, lamp, and radio needed for the trail.','outfit 作动词是提供装备，而不是拿走装备。','meaning'),[q('What clothes made up Nora’s outfit?','wool trousers, a sweater, and waterproof boots','a helmet, a radio, and a map','a survey team and a marsh','这三件衣物组成诺拉的一套服装。'),q('What did the survey outfit do?','mapped the marsh','outfitted hikers with boots','measured the outermost reef marker','勘测团队绘制了沼泽地图。',2,'context'),q('How did the guide outfit each hiker?','by providing a helmet, headlamp, and radio','by removing all safety equipment','by choosing a formal wool suit','向导为徒步者提供所需装备。',3,'context'),q('Which sentence uses outfit as a group noun?','A survey outfit mapped the wetlands.','She wore a blue outfit.','They outfitted every hiker.','第一句中 outfit 指共同工作的团队。',2,'grammar')]);
P('outfits','Outfits is the plural of outfit and refers to coordinated sets of clothing or, in some uses, equipment.',C('outfits.s1','全套服装；行头','The dancers packed three stage outfits each so they could change between performances.','舞者每人打包了三套舞台服装，以便在演出之间换装。','The dancers packed three stage outfits each / so they could change / between performances.','outfits 是 outfit 的复数，常指搭配成套的衣服。','舞者按套准备服装用于换装。'),M('The dancers packed three outfits each but planned to wear no clothing on stage.','The dancers packed three outfits each for changing between performances.','outfit 指服装套装；说准备了服装却计划不穿衣服与语境相反。','meaning'),[q('How many stage outfits did each dancer pack?','three','one hundred','none at all','每位舞者带了三套舞台服装。'),q('Why did they pack several outfits?','to change between performances','to measure the ferry’s outflow','to map the marsh','他们需要在演出之间换装。',1,'context'),q('Which sentence uses outfits as plural clothing sets?','She packed two outfits for the weekend.','The survey outfit mapped the wetland.','The guide outfitted the hikers.','第一句中 outfits 指两套衣服。',1,'grammar'),q('Outfits is the plural of?','outfit','outflow','outset','outfits 是 outfit 的复数形式。',1,'word-formation')]);
P('outfitter','Outfitter combines outfit with the agent suffix -er; it is a person or shop that supplies clothing or outdoor equipment.',C('outfitter.s1','服装商；装备商','The outfitter rented snowshoes and insulated jackets to visitors heading into the mountain reserve.','这家户外装备店把雪鞋和保暖夹克租给前往山地保护区的游客。','The outfitter rented snowshoes and insulated jackets / to visitors / heading into the mountain reserve.','outfitter 指出售或提供衣物、户外装备的人或商店。','商店给游客租借雪鞋和保暖服装。'),M('The outfitter rented snowshoes to hikers but was described as the person who studied orthography and spelling rules.','The outfitter rented snowshoes and outdoor clothing to hikers.','提供服装装备的商店不是研究拼写体系的语言学专家。','distinction'),[q('What did the outfitter rent to visitors?','snowshoes and insulated jackets','a ferry timetable and a train ticket','a medical chart and a microscope','店家租借雪鞋和保暖夹克。'),q('Who is an outfitter?','a shop or person supplying outdoor gear','a patient receiving orthopedics treatment','a person who publishes a spelling guide','outfitter 是提供服装或户外装备的人或商店。',1,'meaning'),q('Where were the visitors heading?','the mountain reserve','the regional clinic','the marsh survey office','游客前往山地保护区。',1,'context'),q('Which word is the base of outfitter?','outfit','outcry','outdistance','outfitter 由 outfit 加 -er 构成。',1,'word-formation')]);
P('outflow','Outflow combines out and flow and means the movement of a substance, money, or people away from a place or system.',C('outflow.s1','外流','The reservoir’s outflow increased after the gates opened to release water downstream.','闸门打开、向下游放水后，水库的流出量增加了。','The reservoir’s outflow increased / after the gates opened / to release water downstream.','outflow 指液体、资金或人员离开某地或系统的流动。','水从水库向下游流出。'),M('The reservoir’s outflow increased after the gates were sealed and no water could leave the basin.','The reservoir’s outflow increased after the gates opened and water moved downstream.','闸门关闭且水无法流出，与 outflow 增加相矛盾。','meaning'),[q('What caused the reservoir’s outflow to increase?','the gates opened to release water','the basin froze solid','the reservoir received no inflow','闸门打开后放水，流出量增加。'),q('What does outflow mean?','movement away from a place or system','water entering a reservoir','a sudden burst of anger','outflow 指向外流动。',1,'meaning'),q('Which is an outflow of money?','funds leaving a company account','revenue entering the account','a report being published','资金离开账户是资金外流。',1,'context'),q('What happened to the released water?','it moved downstream','it returned through the gates upstream','it became an outbuilding','水被放出后流向下游。',1,'context')]);
P('outgas','Outgas combines out and gas and means to release absorbed or dissolved gas, or to remove gas from a material.',C('outgas.s1','放气；除气','The heated resin began to outgas, releasing a sharp-smelling vapour inside the sealed chamber.','加热后的树脂开始释气，在密封舱内释放出刺鼻蒸气。','The heated resin began to outgas / releasing a sharp-smelling vapour / inside the sealed chamber.','outgas 可不及物地表示材料释放气体，也可及物地表示使其除气。','树脂受热后放出蒸气。'),M('The heated resin began to outgas while releasing no gas or vapour of any kind.','The heated resin began to outgas as it released vapour into the chamber.','outgas 表示释放气体，与完全没有释放气体相反。','meaning'),[q('What released vapour in the chamber?','the heated resin','the reservoir gate','the orthopedics patient','受热树脂释放出蒸气。'),q('What does outgas mean here?','release absorbed or dissolved gas','take in water through a membrane','expel a person from office','树脂释出被吸收或溶解的气体。',1,'meaning'),q('Which material is outgassing?','a warm plastic part releasing trapped gas','a sealed metal part releasing no gas','a wet sponge absorbing water','释放内部气体的塑料部件正在 outgas。',1,'context'),q('What happened after the resin was heated?','it emitted vapour','it became a public outcry','it stopped existing','加热后树脂释放蒸气。',1,'context')]);
P('outgassing','Outgassing is the noun formed from outgas + -ing; it is the process by which trapped or dissolved gas escapes from material.',C('outgassing.s1','释气','Engineers measured outgassing from the spacecraft insulation before installing it near sensitive optical equipment.','工程师在把航天器隔热材料装到精密光学设备附近前，测量了它的释气情况。','Engineers measured outgassing from the spacecraft insulation / before installing it / near sensitive optical equipment.','outgassing 指被困或溶解的气体从材料中逸出的过程。','工程师测量隔热材料释放气体的程度。'),M('The engineers measured outgassing from the insulation, although no gas escaped from the material at any time.','The engineers measured outgassing because gas escaped from the insulation material.','outgassing 是气体从材料逸出的过程，与从未逸气相矛盾。','meaning'),[q('What material was checked for outgassing?','spacecraft insulation','a ferry’s ticket booth','a limestone outcrop','工程师检查航天器隔热材料。'),q('Why measure outgassing near optical equipment?','escaping gas could affect sensitive instruments','the equipment needed an outdoor outfit','the insulation had caused an election outcry','测释气可评估逸出气体对精密仪器的影响。',1,'context'),q('Outgassing is the process of?','trapped gas escaping from a material','water moving through a membrane','a person leaving office','outgassing 指材料释出气体。',1,'meaning'),q('Which form names the process related to the verb outgas?','outgassing','outgone','outgased','outgassing 是 outgas 的过程名词。',1,'word-formation')]);
P('outgoing','Outgoing combines out and going; it can mean sociable, about to leave a post, or travelling away from a place.',[C('outgoing.s1','外向的；爱交际的','The outgoing volunteer greeted new members and quickly learned everyone’s name.','这位性格外向的志愿者热情招呼新成员，很快记住了每个人的名字。','The outgoing volunteer greeted new members / and quickly learned / everyone’s name.','outgoing 可形容友善健谈、乐于与人交往的人。','主动问候新成员体现亲切外向。'),C('outgoing.s2','即将离任的；卸任的','The outgoing director handed the project files to her successor on the final day of her appointment.','任期最后一天，即将离任的主任把项目文件交给了继任者。','The outgoing director handed the project files / to her successor / on the final day of her appointment.','outgoing 也可指即将离开职位或任期的人。','她正在把职责交给继任者。'),C('outgoing.s3','往外的；出发的','The control tower delayed an outgoing flight while an incoming aircraft landed.','一架进港飞机降落时，塔台延误了一班出港航班。','The control tower delayed an outgoing flight / while an incoming aircraft / landed.','outgoing 还可形容离开某地的交通、信件或流量。','航班正要离开机场。')],M('The outgoing director handed files to her successor but was described as staying in office for another decade.','The outgoing director handed files to her successor on her final day in office.','outgoing 描述即将离职的人，与继续留任十年相反。','meaning'),[q('How did the volunteer behave toward new members?','she greeted them warmly and learned their names','she refused to speak to anyone','she delayed their outgoing flight','她热情问候新成员，表现得外向友好。'),q('What did the outgoing director hand over?','project files','the airport control tower','the volunteers’ outfits','主任把项目文件交给继任者。',2,'context'),q('Which vehicle is outgoing?','a bus leaving the station','a bus arriving at the station','a director staying in office','离开车站的公交车是 outgoing。',3,'context'),q('Which sense of outgoing describes a friendly person?','sociable and willing to talk','about to leave an official position','travelling away from a place','第一义项描述爱交际的人。',1,'meaning')]);
P('outgrow','Outgrow combines out and grow; it means to become too large or mature for something, or to surpass another in growth.',C('outgrow.s1','不再适合；超越','Milo outgrew his first bicycle before the end of the summer and needed a larger frame.','夏天还没结束，米洛就长得骑不下第一辆自行车了，需要换更大的车架。','Milo outgrew his first bicycle / before the end of the summer / and needed a larger frame.','outgrow 可表示长大到不再适合某物，也可表示成长超过某人或某物。','米洛长高后需要更大的自行车。'),M('Milo outgrew his bicycle, so he continued to fit comfortably on its tiny frame as he grew taller.','Milo outgrew his bicycle and no longer fit its small frame as he grew taller.','outgrow 表示长大到不再适合，不能同时说仍舒适地适合小车架。','meaning'),[q('Why did Milo need a larger bicycle frame?','he had grown too large for the first bike','the first bike’s frame had become an outbuilding','the bike had outgassed','米洛长大后骑不下第一辆自行车。'),q('What does outgrow mean in this sentence?','become too large for something','leave a building through its outer door','make a product sell more copies','这里表示成长到不再适合。',1,'meaning'),q('Which child has outgrown a coat?','a child whose sleeves and body are now too short','a child who still fits the coat perfectly','a child who has never worn the coat','袖子和衣身都变短说明孩子长大后不再适合。',1,'context'),q('Outgrow can also mean?','surpass another in growth','release gas from plastic','protest a closure publicly','outgrow 也可指生长超过另一方。',1,'meaning')]);
P('outgrowth','Outgrowth combines out and growth and means a development or product that arises from an earlier process or idea.',C('outgrowth.s1','自然结果；派生物','The neighborhood garden was an outgrowth of a school project that taught children how to grow vegetables.','社区菜园源自一项学校项目，该项目教孩子们种植蔬菜。','The neighborhood garden was an outgrowth / of a school project / that taught children how to grow vegetables.','outgrowth 指由先前活动或想法发展而来的结果。','菜园是学校种植项目进一步发展出的成果。'),M('The garden was an outgrowth of the school project, although it had no connection to the project or to the children involved.','The garden was an outgrowth of the school project, expanding the children’s planting work into the neighborhood.','outgrowth 表示由早先活动发展而来；完全无关的事物不是该项目的结果。','meaning'),[q('What earlier project led to the neighborhood garden?','a school project teaching vegetable growing','a campaign to close the garden','a course in Greek spelling','学校的种菜项目发展成社区菜园。'),q('What does outgrowth mean?','a result that develops from an earlier activity','a separate building behind a farmhouse','a person forced from office','菜园是先前项目发展出来的成果。',1,'meaning'),q('Which could be an outgrowth of a reading club?','a community library started by its members','a river outflow with no relation to readers','a train leaving the station','由读书会成员创建的社区图书馆是其派生成果。',1,'context'),q('How is the garden related to the school project?','it grew from and extended the project’s work','it was built before the project began','it replaced the children who ran the project','它由学校项目发展而来并延续了其工作。',1,'context')]);
P('outhouse','Outhouse combines out and house and means a small separate building outside a main house, especially an outdoor toilet.',C('outhouse.s1','外屋；户外厕所','The hikers found an outhouse behind the remote cabin, away from the sleeping rooms.','徒步者在偏远小屋后面、远离卧室的地方找到了一间户外厕所。','The hikers found an outhouse behind the remote cabin / away from / the sleeping rooms.','outhouse 指主屋外的小型附属建筑，尤指户外厕所。','它与睡觉的小屋分开建造。'),M('The cabin’s outhouse was the main bedroom inside the house, directly beside the kitchen.','The cabin’s outhouse was a small separate toilet building behind the house.','独立位于主屋外的厕所不是主屋内部的卧室。','meaning'),[q('Where did the hikers find the outhouse?','behind the remote cabin','inside the main sleeping room','at the airport gate','户外厕所位于小屋后面。'),q('What can an outhouse especially mean?','a small outdoor toilet building','a room in the main house’s centre','a place where trains depart','outhouse 尤指建在主屋外的小厕所。',1,'meaning'),q('Which structure is an outhouse?','a detached toilet behind a rural home','the home’s indoor bathroom beside the kitchen','the main farmhouse itself','独立在房屋外的厕所符合定义。',1,'context'),q('The word is transparently formed from?','out + house','our + house','out + horse','outhouse 由 out 和 house 组成。',1,'word-formation')]);
P('outing','Outing is formed from out + -ing; it can mean a short pleasure trip or the non-consensual disclosure of private identity.',[C('outing.s1','出游；远足；短途旅行','The class took an outing to the coastal reserve to observe nesting ospreys.','全班去海岸保护区短途游览，观察筑巢的鹗。','The class took an outing / to the coastal reserve / to observe nesting ospreys.','outing 可指为了游玩或学习而进行的短途旅行。','全班前往保护区观察鸟类。'),C('outing.s2','曝光；公开某人的隐私身份','The journalist apologised for the outing of the activist’s private identity without consent.','记者为未经同意曝光这位活动人士的隐私身份而道歉。','The journalist apologised for the outing / of the activist’s private identity / without consent.','outing 也可指未经当事人同意披露其私人身份信息。','未经同意的披露构成侵犯隐私。')],M('The class’s outing to the reserve was a private identity disclosure, although every student simply went birdwatching.','The class’s outing was a short educational trip to observe birds at the reserve.','去保护区观察鸟类是短途旅行，不是曝光某人的私人身份。','distinction'),[q('Where did the class go on its outing?','the coastal reserve','the manager’s regional office','the orthopedics ward','班级去海岸保护区短途游览。'),q('What did the journalist apologise for?','revealing a private identity without consent','taking students to see ospreys','delaying an outbound train','记者为未经同意曝光隐私身份而道歉。',2,'context'),q('Which sentence uses outing to mean a trip?','Our outing to the coast lasted one afternoon.','The outing of her private identity was harmful.','The hikers outgrew their boots.','第一句指去海边短途游览。',1,'meaning'),q('Which outing violates privacy in this entry?','publishing someone’s private identity without permission','taking a class to a nature reserve','walking with friends to watch birds','未经允许披露身份属于侵犯隐私。',2,'meaning')]);
P('outlast','Outlast combines out and last and means to continue in existence or use after another thing has ended.',C('outlast.s1','比……更长久','The stone footbridge outlasted several wooden bridges that storms had washed away.','这座石制人行桥比几座被暴风雨冲走的木桥更耐久。','The stone footbridge outlasted several wooden bridges / that storms / had washed away.','outlast 表示持续时间超过另一物或在其之后仍存在。','石桥仍在，而木桥已被冲毁。'),M('The stone bridge outlasted the wooden bridge because it collapsed years before the wooden one was built.','The stone bridge outlasted the wooden bridge because it remained after the wooden one was washed away.','先于木桥建成且更早坍塌的石桥不可能比木桥存在得更久。','meaning'),[q('What happened to the wooden bridges?','storms washed them away','they outlasted the stone bridge','they became outdoor clothing','木桥被暴风雨冲走。'),q('What does the stone bridge outlast?','several wooden bridges','the storms that built it','the hikers’ outing','石桥的存在时间超过几座木桥。',1,'context'),q('Which object outlasted the others?','a stone sign still standing after wooden signs rotted','a wooden sign that disappeared first','a temporary paper notice','石制标牌在木牌腐朽后仍存在，因而更持久。',1,'meaning'),q('Outlast most nearly means?','remain longer than','leave a place by train','suddenly express anger','outlast 指比……更长久。',1,'meaning')]);
P('outlaw','Outlaw came from Old Norse útlagi, “one put outside the law”; as a noun it is a fugitive, and as a verb it means to make illegal.',[C('outlaw.s1','亡命之徒；逃犯；绿林人物','The outlaw hid in the hills after escaping custody and avoiding the patrols sent to find him.','这名逃犯越狱并躲过搜捕巡逻队后，藏身山中。','The outlaw hid in the hills / after escaping custody / and avoiding the patrols sent to find him.','outlaw 作名词指违法后躲避当局的人。','逃脱羁押并躲避巡逻队的是逃犯。'),C('outlaw.s2','宣布……为非法；禁止','The city voted to outlaw the sale of fireworks near the hospital after several fires broke out.','发生数起火灾后，市议会投票禁止在医院附近销售烟花。','The city voted to outlaw the sale of fireworks / near the hospital / after several fires broke out.','outlaw 作动词表示通过法律或正式决定禁止某事。','市议会决定禁止出售烟花。')],M('The city outlawed fireworks near the hospital, meaning it officially required shops to sell them there.','The city outlawed fireworks near the hospital, meaning it officially prohibited their sale there.','outlaw 作动词是正式禁止，不能解释为要求继续销售。','meaning'),[q('Where did the outlaw hide?','in the hills','at the hospital fireworks shop','inside the city council chamber','逃犯躲藏在山中。'),q('What did the city vote to outlaw?','fireworks sales near the hospital','all medical treatment','every outdoor activity','市议会投票禁止医院附近销售烟花。',2,'context'),q('Which use makes outlaw a verb?','The council outlawed fireworks near the clinic.','The outlaw hid from patrols.','The outlaw was caught in the hills.','第一句中 outlawed 表示正式禁止。',2,'grammar'),q('What does outlaw mean as a noun?','a fugitive outside the protection of the law','a person who measures a river’s outflow','a sociable departing director','名词 outlaw 指躲避当局的逃犯。',1,'meaning')]);
P('outlay','Outlay comes from the verb phrase lay out, “to spend,” with the elements out + lay; it can mean an amount spent or the act of spending money.',[C('outlay.s1','经费，支出','The initial outlay for the solar panels was high, but lower electricity bills are expected to repay it.','太阳能电池板的初始支出很高，但预计较低的电费会逐步抵偿这笔费用。','The initial outlay for the solar panels / was high / but lower electricity bills are expected to repay it.','outlay 作名词指为某种用途支出的一笔钱。','安装太阳能板需要一次性投入。'),C('outlay.s2','花费','The museum will outlay additional funds to stabilize the ancient wall before winter.','博物馆将在冬季前额外拨款加固古墙。','The museum will outlay additional funds / to stabilize the ancient wall / before winter.','outlay 也可作动词，表示为某项目花钱。','博物馆为加固城墙拨出经费。')],M('The museum will outlay additional funds on the wall, meaning it will receive rather than spend the money.','The museum will outlay additional funds on the wall, meaning it will spend that money on repairs.','outlay 作动词表示支出，不能解释成收到资金。','meaning'),[q('What was high at the start of the solar project?','the initial cost','the number of outlying towns','the museum’s ticket sales','太阳能板的初始支出较高。'),q('What will the museum do before winter?','spend extra funds to stabilize the wall','sell the wall to an outfitter','outlaw all repairs','博物馆将拨款加固古墙。',2,'context'),q('Which sentence uses outlay as a noun?','The initial outlay was larger than expected.','The museum will outlay more funds.','The museum outlined the repair plan.','第一句中 outlay 指一笔支出。',1,'grammar'),q('What does the verb outlay mean?','spend money for a purpose','receive money as a payment','count a crowd in a stadium','outlay 作动词表示花钱。',2,'meaning')]);
P('outlet','Outlet combines out and let, “to allow to go out”; it can mean an opening, an emotional channel, a retail shop, or an electrical socket.',[C('outlet.s1','出口；排放口','The storm drain outlet empties into the stream well below the town’s drinking-water intake.','雨水管排放口在城镇饮用水取水口下游很远处通入溪流。','The storm drain outlet empties into the stream / well below the town’s drinking-water intake.','outlet 可指液体或气体离开管道、系统的出口。','雨水经排放口流入溪流。'),C('outlet.s2','发泄途径；表现渠道','After retiring from competition, he found a creative outlet in restoring old racing boats.','退出竞赛后，他在修复旧赛艇中找到了发挥创造力的途径。','After retiring from competition / he found a creative outlet / in restoring old racing boats.','outlet 可比喻表达情绪或发挥精力的渠道。','修船为他提供了发挥兴趣的渠道。'),C('outlet.s3','专卖店；折扣店；经销点','We bought the previous season’s jackets at a factory outlet near the highway.','我们在公路附近的工厂直销店买了上一季的夹克。','We bought the previous season’s jackets / at a factory outlet / near the highway.','outlet 也可指制造商直营的零售店，常以较低价格售货。','商店出售上一季的服装。'),C('outlet.s4','电源插座','The lamp would not turn on until I plugged its cord into a wall outlet.','我把灯线插进墙上插座后，灯才亮起来。','The lamp would not turn on / until I plugged its cord / into a wall outlet.','outlet 还可指墙上的电源插座。','电灯通过插座接通电源。')],M('I plugged the lamp into the wall outlet, which is the pipe opening where storm water leaves the drain.','I plugged the lamp into the wall outlet, the electrical socket that supplies power.','给电灯插电时 wall outlet 指插座，不是排水管出口。','distinction'),[q('Where did the storm drain empty?','into the stream','into a factory outlet','into the lamp’s wall socket','雨水管排放口通入溪流。'),q('What creative outlet did the retired racer find?','restoring old racing boats','plugging a lamp into a socket','buying last season’s jackets','修复旧赛艇成为他发挥创造力的渠道。',2,'context'),q('Where did the lamp cord go?','into a wall outlet','into the storm drain','into the jacket sleeve','灯线插进墙上插座。',4,'context'),q('Which outlet is a retail shop?','a factory outlet selling discounted jackets','a wall outlet powering a lamp','a drain outlet releasing water','第一项是出售商品的零售店。',3,'meaning')]);
P('outline','Outline combines out and line; it can name a contour or summary, and as a verb it means to summarize or draw a contour.',[C('outline.s1','轮廓；外形','At dusk, the outline of the lighthouse appeared against the orange sky.','黄昏时，灯塔的轮廓映在橙色天空上。','At dusk / the outline of the lighthouse appeared / against the orange sky.','outline 作名词可指物体外边缘形成的轮廓。','灯塔的外形在天空映衬下清晰可见。'),C('outline.s2','大纲；提纲；概要','The proposal begins with an outline of the three stages of the river-restoration project.','提案先概述河流修复项目的三个阶段。','The proposal begins with an outline / of the three stages / of the river-restoration project.','outline 作名词也可指只列主要内容、不含细节的大纲。','大纲列出项目的三个阶段。'),C('outline.s3','概述；勾勒要点','The director outlined the safety changes before inviting questions from the staff.','主任先概述了安全改动，然后请员工提问。','The director outlined the safety changes / before inviting questions / from the staff.','outline 作动词可简要说明主要观点或安排。','主任只说明安全改动的要点。'),C('outline.s4','描出轮廓','The artist outlined the mountain ridge in charcoal before adding colour to the map.','画家先用木炭描出山脊轮廓，再给地图上色。','The artist outlined the mountain ridge / in charcoal / before adding colour to the map.','outline 作动词还可表示画出某物的外边线。','木炭线先勾出山脊外形。')],M('The director outlined every detail of the project in a long appendix but called the document a brief outline with no details.','The director outlined the project’s main stages briefly and left detailed procedures for the appendix.','outline 动词表示概述要点；把完整细节都说完又称不含细节，前后矛盾。','meaning'),[q('What shape appeared against the sunset?','the lighthouse’s outline','the project’s expenditure','a storm drain outlet','天空映出了灯塔的轮廓。'),q('What did the proposal’s outline contain?','the project’s three main stages','every construction instruction in full','a drawing of a wall socket','大纲列出河流修复项目的三个阶段。',2,'context'),q('What did the director do before questions?','summarized the safety changes','drew a lighthouse in charcoal','plugged in a lamp','主任先概述安全改动。',3,'context'),q('Which sentence uses outline to mean draw an edge?','She outlined the ridge on the map.','She outlined the plan in a short speech.','She read the outline of the project.','第一句表示描出山脊轮廓。',4,'meaning')]);
P('outlive','Outlive combines out and live and means to live longer than another person or to continue after something ends.',C('outlive.s1','比……活得长','The old tortoise outlived several owners and remained in the sanctuary for more than a century.','这只老陆龟比几任饲主都活得长，在保护中心待了一百多年。','The old tortoise outlived several owners / and remained in the sanctuary / for more than a century.','outlive 指寿命长于某人或某物，也可指在某事物消失后继续存在。','陆龟的寿命超过了几任饲主。'),M('The tortoise outlived its owner, who survived it by several decades and cared for it until the end.','The tortoise outlived its owner and remained in the sanctuary after the owner died.','若饲主比陆龟多活几十年，陆龟就没有比饲主活得长。','meaning'),[q('Where did the tortoise remain?','in the sanctuary','at the river outflow','inside the factory outlet','陆龟在保护中心继续生活。'),q('What does outlive mean in the example?','live longer than someone','spend money on a project','draw a contour','outlive 表示活得比别人长。',1,'meaning'),q('Which building outlived the others?','a stone hall still standing after nearby wooden halls collapsed','a wooden hall that collapsed first','a temporary tent removed after one day','石厅在其他木厅坍塌后仍存在，存续更久。',1,'context'),q('How long had the tortoise remained at the sanctuary?','more than a century','one afternoon','only until its first owner arrived','陆龟在保护中心待了一百多年。',1,'context')]);
P('outlook','Outlook combines out and look; it can mean a person’s general attitude or the expected future of a situation.',[C('outlook.s1','观点；看法；世界观','Her optimistic outlook helped the team keep working through months of difficult field conditions.','她乐观的人生态度帮助团队熬过了数月艰苦的野外条件。','Her optimistic outlook helped the team / keep working / through difficult field conditions.','outlook 可指一个人看待生活或某个主题的总体态度。','乐观态度影响了团队面对困难的方式。'),C('outlook.s2','前景；展望','The economic outlook improved after the port reopened and local exporters resumed shipping.','港口重新开放、本地出口商恢复发货后，经济前景有所改善。','The economic outlook improved / after the port reopened / and exporters resumed shipping.','outlook 也可指对某种形势未来发展的预期。','港口恢复运营使未来经济预期转好。')],M('The port reopened and exporters resumed shipping, so the economic outlook worsened because trade had stopped permanently.','The port reopened and exporters resumed shipping, so the economic outlook improved.','贸易恢复通常会改善此处所说的经济前景，错误句又称贸易永久停摆。','meaning'),[q('What helped the team endure field conditions?','the researcher’s optimistic attitude','a new retail outlet','a longer outburst','她乐观的态度帮助团队坚持工作。'),q('What improved when the port reopened?','the economic outlook','the lighthouse’s outline','the outflow of resentment','港口复开后经济前景改善。',2,'context'),q('Which phrase uses outlook for a person’s attitude?','a cheerful outlook on life','the economic outlook for next year','the weather outlook on the radio','第一项描述对生活的总体态度。',1,'meaning'),q('In “the economic outlook improved,” outlook means?','the expected future condition','a person’s clothing set','the amount of money already spent','这里指对未来经济形势的预期。',2,'meaning')]);
P('outlying','Outlying combines out and lying and describes a place situated far from a centre or main area.',C('outlying.s1','偏远的，远离中心的','The mobile clinic visits outlying villages that are several hours from the nearest hospital.','流动诊所会前往离最近医院有数小时路程的偏远村庄。','The mobile clinic visits outlying villages / that are several hours / from the nearest hospital.','outlying 描述远离中心地区或主要聚居地的地方。','这些村庄离最近医院很远。'),M('The outlying village stood in the city centre beside the central hospital and main railway station.','The outlying village stood far from the city centre and the nearest hospital.','位于城市中心并紧邻医院的村庄不是偏远地区。','meaning'),[q('How far are the outlying villages from a hospital?','several hours away','one minute away in the city centre','inside the hospital building','这些村庄离医院有数小时路程。'),q('What does outlying describe?','far from a main centre','located at the exact centre','about to leave a position','outlying 指远离中心区域。',1,'meaning'),q('Which place is outlying?','a small settlement far beyond the main town','a hospital beside the central station','a village square in the city centre','远离主镇的小聚居点是 outlying。',1,'context'),q('Why does the mobile clinic travel there?','to reach residents far from the nearest hospital','to sell clothes at a factory outlet','to map a lighthouse outline','流动诊所前往偏远村庄提供医疗服务。',1,'context')]);
P('outmoded','Outmoded combines out and mode and means replaced by newer ideas, styles, or methods.',C('outmoded.s1','过时的','The library stopped using its outmoded card catalogue and moved the records into a searchable database.','图书馆停止使用过时的卡片目录，把资料转入可检索的数据库。','The library stopped using its outmoded card catalogue / and moved the records / into a searchable database.','outmoded 指已被更新观念、款式或方法取代的。','可检索数据库取代了旧式卡片目录。'),M('The library called its card catalogue outmoded, even though it was the newest system and had just replaced the database.','The library called its card catalogue outmoded because the newer searchable database had replaced it.','被新系统取代的旧目录才是 outmoded；“最新系统”与此相反。','meaning'),[q('What replaced the card catalogue?','a searchable database','an outbuilding','an outgoing flight','图书馆把目录转入可检索数据库。'),q('What does outmoded mean?','replaced by a newer method or style','recently invented and widely adopted','located far from a centre','outmoded 指已经被新方法或新式样取代。',1,'meaning'),q('Which tool is outmoded?','a paper directory replaced by an online search system','a database updated this morning','a new device adopted by every library','被在线系统取代的纸质目录已经过时。',1,'context'),q('Why did the library stop using the old catalogue?','a newer searchable system took its place','the catalogue had become an outflow','the library had outnumbered its readers','新数据库取代了旧卡片目录。',1,'context')]);
P('outnumber','Outnumber combines out and number and means to be greater in number than another group.',C('outnumber.s1','在数量上超过','At the meeting, residents who supported the trail outnumbered those who wanted the project cancelled.','会上，支持修建步道的居民人数多于希望取消项目的人。','At the meeting / residents who supported the trail outnumbered / those who wanted the project cancelled.','outnumber 表示一方的数量超过另一方。','支持者人数更多。'),M('Supporters outnumbered opponents, meaning there were fewer supporters than opponents at the meeting.','Supporters outnumbered opponents, meaning there were more supporters than opponents at the meeting.','outnumber 表示数量更多，不是更少。','meaning'),[q('Which residents were more numerous?','those who supported the trail','those who wanted cancellation','the meeting organizers only','支持步道的居民人数更多。'),q('What does outnumber mean?','be greater in number than another group','sell more products than a rival','move farther from a centre','outnumber 表示数量超过。',1,'meaning'),q('Which team outnumbers its rivals?','a team with twelve players facing a team of eight','a team with fewer players than its rivals','two teams with exactly equal numbers','十二人队在人数上超过八人队。',1,'context'),q('What was the balance at the meeting?','trail supporters were more numerous','cancellation supporters were more numerous','both groups were absent','支持步道者多于反对项目者。',1,'context')]);
P('outpost','Outpost combines out and post and originally referred to a military position set apart from the main force; it is a small remote station or settlement.',C('outpost.s1','前哨站；边远聚居地','The research outpost on the island stores fuel and radio equipment for teams studying seabirds.','岛上的研究前哨站为研究海鸟的团队储存燃料和无线电设备。','The research outpost on the island / stores fuel and radio equipment / for seabird teams.','outpost 指远离主要区域、供贸易、军事或研究使用的小型据点。','岛上据点远离大陆，为研究团队提供物资。'),M('The island outpost stood in the crowded city centre beside the national headquarters and served no remote area.','The island outpost stood far from the mainland and supported research teams working in a remote area.','位于市中心且不服务偏远地区的地点不符合 outpost 的定义。','meaning'),[q('Where was the research outpost?','on an island','in the city centre','inside the main airport terminal','研究前哨站位于岛上。'),q('What did the outpost store for the teams?','fuel and radio equipment','factory-outlet clothing','a wall outlet and a lighthouse map','前哨站储存燃料和无线电设备。',1,'context'),q('What is an outpost?','a small station far from a main centre','a large central government office','a public protest about a closure','outpost 指边远的小型据点。',1,'meaning'),q('Which feature makes this site an outpost?','its remote island location','its place beside the national headquarters','its role as a retail clothing shop','它远离大陆，位于偏远地区。',1,'context')]);
P('outpouring','Outpouring combines out and pour and names a strong expression or flow of emotion, words, gifts, or liquid.',C('outpouring.s1','迸发；倾泻','The nurse received an outpouring of thank-you letters from families after the flood shelter closed.','洪水避难所关闭后，这名护士收到了家属们纷纷寄来的感谢信。','The nurse received an outpouring of thank-you letters / from families / after the flood shelter closed.','outpouring 可指情感或言语的集中表达，也可指大量涌出的液体或物品。','许多家庭集中表达了感谢。'),M('The nurse received an outpouring of thank-you letters, meaning every family withheld all messages and sent nothing.','The nurse received an outpouring of thank-you letters as many families sent messages of gratitude.','outpouring 指大量涌出或集中表达；一封也没有就不能称为大量来信。','meaning'),[q('What did families send the nurse?','many letters expressing thanks','a single invoice for the outlay','an outdated timetable','家属寄来大量感谢信。'),q('Why did the nurse receive the letters?','families wanted to thank her after the shelter closed','the nurse had outnumbered the families','the shelter had an electrical outlet','避难所关闭后，家属集中表达谢意。',1,'context'),q('Which is an outpouring of emotion?','a large wave of public gratitude','one quiet thought kept private','a small amount of water in a glass','大量公开表达感谢属于情感迸发。',1,'meaning'),q('The word outpouring suggests?','a strong or abundant flow outward','a complete lack of expression','a person leaving a post','outpouring 含有大量涌出或表达的意味。',1,'meaning')]);
P('output','Output combines out and put and names what is produced, a machine’s signal or information, or the act of sending data out.',[C('output.s1','产量；产出','The mill increased its weekly output after installing a faster grain sorter.','安装速度更快的谷物分选机后，磨坊提高了每周产量。','The mill increased its weekly output / after installing / a faster grain sorter.','output 可指生产出的商品、工作成果或能源数量。','新设备提高了每周产量。'),C('output.s2','输出；输出信息','The monitor’s audio output was too quiet, so the technician replaced its cable.','显示器的音频输出太小，技术员因此更换了线缆。','The monitor’s audio output was too quiet / so the technician / replaced its cable.','output 也可指机器或程序产生的声音、信息或功率。','音频设备产生的输出信号过小。'),C('output.s3','输出','The script outputs a separate report for each region when the user selects the annual summary.','用户选择年度汇总时，脚本会为每个地区输出一份单独报告。','The script outputs a separate report / for each region / when the user selects the annual summary.','output 作动词表示让计算机或设备发出数据或结果。','脚本生成并输出报告。')],M('The script outputs a separate report for every region, but its output contains no reports or data at all.','The script outputs a separate report for every region, and its output contains those reports.','动词说明脚本生成报告，不能同时说输出里完全没有报告或数据。','meaning'),[q('What increased at the mill?','its weekly production','the number of outlying villages','the price of the factory outfit','磨坊的每周产量提高了。'),q('Why did the technician replace the cable?','the audio output was too quiet','the grain output was too high','the script had an outburst','音频输出过小，所以更换线缆。',2,'context'),q('Which sentence uses output as a verb?','The program outputs a report for each region.','The mill’s output rose this year.','The monitor’s audio output was quiet.','第一句中 outputs 表示输出报告。',3,'grammar'),q('Which is a machine output?','a sound signal produced by a monitor','a grain shipment entering the mill','an electrical outlet in the wall','显示器产生的声音信号属于设备输出。',2,'meaning')]);
P('outrage','Outrage came through French from Latin ultra, “beyond”; it can mean shocked anger, a shocking act, or to make someone very angry.',[C('outrage.s1','愤慨；震怒','Residents expressed outrage when the council approved dumping waste beside the children’s playground.','市议会批准在儿童游乐场旁倾倒废弃物后，居民表达了愤慨。','Residents expressed outrage / when the council approved / dumping waste beside the playground.','outrage 作名词可指对不公或残酷之事感到强烈愤怒和震惊。','居民因危害儿童的决定而愤慨。'),C('outrage.s2','暴行；骇人听闻的事','The report called the deliberate poisoning of the river an outrage against the whole community.','报告称蓄意污染河流是对整个社区的骇人暴行。','The report called the deliberate poisoning of the river / an outrage / against the whole community.','outrage 也可指令人震惊、残酷或不可接受的行为。','蓄意污染河流被称为恶劣行径。'),C('outrage.s3','使震怒；激怒','The false accusation outraged the nurse, who had spent the night helping stranded families.','这项虚假指控激怒了那名护士；她前一晚一直在帮助受困家庭。','The false accusation outraged the nurse / who had spent the night / helping stranded families.','outrage 作动词表示使某人非常愤怒或震惊。','虚假指控使护士震怒。')],M('The false accusation outraged the nurse, but she felt no anger, shock, or objection to it.','The false accusation outraged the nurse, making her feel intense anger and shock.','outrage 作动词表示引起强烈愤怒，错误句却否认了任何愤怒或震惊。','meaning'),[q('What decision caused residents’ outrage?','approving waste dumping near a playground','building a detached outhouse','increasing the mill’s output','居民因批准在游乐场旁倾倒废物而愤慨。'),q('What did the report call an outrage?','deliberately poisoning the river','publishing a new safety outline','an outflow of clean water','报告把蓄意污染河流称为恶劣行为。',2,'context'),q('What outraged the nurse?','a false accusation','a thank-you letter','an accurate medical result','虚假指控激怒了护士。',3,'context'),q('Which sentence uses outrage as a verb?','The decision outraged local families.','The families expressed outrage.','The act was an outrage.','第一句中 outraged 表示使人愤怒。',3,'grammar')]);
P('outraged','Outraged is the past participle of outrage used as an adjective; it means feeling or showing intense anger.',C('outraged.s1','愤怒的','The outraged passengers demanded an explanation after the airline cancelled the last flight without warning.','航空公司毫无预警地取消末班航班后，愤怒的乘客要求解释。','The outraged passengers demanded an explanation / after the airline cancelled / the last flight without warning.','outraged 描述因不公、冒犯或震惊事件而愤怒的人。','旅客因突然取消航班而愤怒。'),M('The outraged passengers calmly praised the airline for cancelling their flight without warning and asked for no explanation.','The outraged passengers angrily demanded an explanation for the unannounced cancellation.','愤怒的乘客不会因突发取消而平静赞扬航空公司。','meaning'),[q('What had the airline done?','cancelled the last flight without warning','added an outbound flight','opened an electrical outlet','航空公司没有预警就取消了末班航班。'),q('What did the outraged passengers demand?','an explanation','an outbuilding','an orthography lesson','乘客要求航空公司解释。',1,'context'),q('Which person is outraged?','someone showing intense anger after an unfair cancellation','someone calmly satisfied with the service','someone who merely outlines a route','遭遇不公取消后十分愤怒的人是 outraged。',1,'meaning'),q('Outraged is grammatically used here as?','an adjective describing passengers','a noun for the cancellation','a verb meaning to sell more','outraged 修饰 passengers，是形容词。',1,'grammar')]);
P('outrageous','Outrageous is formed from outrage + -ous and means extremely shocking, unfair, or unacceptable.',C('outrageous.s1','令人愤慨的；骇人的','The landlord’s outrageous demand for six months of rent in advance shocked the tenants.','房东要求预付六个月租金的离谱条件让租户震惊。','The landlord’s outrageous demand / for six months of rent in advance / shocked the tenants.','outrageous 形容极其令人震惊、不公平或无法接受的事。','要求预付半年房租超出合理范围。'),M('The landlord’s outrageous demand was entirely fair and ordinary, and no tenant found it surprising or unacceptable.','The landlord’s outrageous demand was shocking and unreasonable to the tenants.','outrageous 意为令人震惊或不可接受，不能同时说它平常合理且毫不意外。','meaning'),[q('What did the landlord demand?','six months of rent in advance','a year of free housing','a new outbuilding','房东要求预付半年租金。'),q('Why was the demand outrageous?','it was shocking and unreasonable','it matched the ordinary monthly agreement','it had no effect on the tenants','预付六个月租金的要求令人难以接受。',1,'context'),q('Which action is outrageous?','charging a family an impossible fee for a basic repair','charging the posted fair price','offering a clear written receipt','不合理地收取高额维修费令人震惊。',1,'meaning'),q('What does the suffix -ous do in outrageous?','forms an adjective meaning characterized by or full of outrage','forms a past-tense verb','forms a plural noun','-ous 使词成为表示特征的形容词。',1,'word-formation')]);
P('outrageously','Outrageously is the adverb formed from outrageous + -ly; it means to a shockingly excessive, unfair, or unacceptable degree.',C('outrageously.s1','过分地；猖狂地','The contractor charged outrageously high fees for repairs that should have taken only an hour.','承包商对本应只需一小时的维修收取了高得离谱的费用。','The contractor charged outrageously high fees / for repairs / that should have taken only an hour.','outrageously 修饰形容词或动词，表示程度高到令人震惊或无法接受。','费用高得离谱。'),M('The contractor charged outrageously low fees that were fair, modest, and completely ordinary.','The contractor charged outrageously high fees that were unfairly excessive.','outrageously 表示程度过分或令人震惊，不能修饰公平且极低的费用。','meaning'),[q('What did the contractor charge?','very high repair fees','no fee at all','a standard fee for an hour of work','承包商收取了高额维修费。'),q('Why were the fees outrageous?','the repair should have taken only an hour','the contractor gave every repair away free','the fees exactly matched the posted estimate','维修时间很短，但收费高得离谱。',1,'context'),q('Which word does outrageously modify in the example?','high','contractor','repairs','outrageously 修饰形容词 high。',1,'grammar'),q('Outrageously most nearly means?','to an extremely excessive degree','in a quietly reasonable manner','at the beginning of a process','这里表示程度过分、令人震惊。',1,'meaning')]);
P('outreach','Outreach combines out and reach and names organized efforts to contact more people or extend services beyond the usual group.',C('outreach.s1','外展服务；扩大触及','The library’s outreach program brings books and reading sessions to residents in remote villages.','图书馆的外展项目把书籍和阅读活动带到偏远村庄的居民中。','The library’s outreach program brings books and reading sessions / to residents / in remote villages.','outreach 指主动接触通常服务范围之外的人群或扩大服务覆盖。','图书馆把阅读服务送到偏远村庄。'),M('The library called its outreach program a service for remote villages, but it refused to contact or visit anyone outside the city centre.','The library’s outreach program visits remote villages and brings reading services to residents there.','outreach 意味着主动扩大接触范围，完全拒绝离开市中心与此矛盾。','meaning'),[q('Who receives the library’s outreach service?','residents of remote villages','only staff at the central office','passengers on an outbound train','图书馆把阅读服务带到偏远村庄。'),q('What does outreach aim to do?','reach people beyond the usual service group','exclude people from a community','outnumber a rival organization','outreach 是扩大服务触及人群。',1,'meaning'),q('What does the library bring to the villages?','books and reading sessions','rent invoices and ferry timetables','orthopedics equipment','外展项目提供书籍和阅读活动。',1,'context'),q('Which is an outreach activity?','a clinic visiting a remote community to offer screenings','a clinic serving only people who already live beside it','a shop closing its outlying branch','到偏远社区提供检查属于外展服务。',1,'meaning')]);
P('outrigger','Outrigger names a support frame or float projecting outside a canoe’s hull; its precise word-history beyond the English compound is uncertain.',C('outrigger.s1','舷外浮架','The canoe’s outrigger kept the narrow hull steady as the crew crossed choppy water.','船员穿越波涛时，独木舟的舷外浮架使狭窄船体保持稳定。','The canoe’s outrigger kept the narrow hull steady / as the crew crossed / choppy water.','outrigger 指固定在船体外侧、用于增强稳定性的支架或浮体。','外侧浮架防止窄船体倾覆。'),M('The outrigger was fixed inside the canoe and made the narrow hull less stable in rough water.','The outrigger projected outside the canoe and helped keep its narrow hull stable.','舷外浮架安装在船体外侧并增强稳定性，不是装在船内使船更不稳。','meaning'),[q('What did the outrigger do?','kept the canoe’s narrow hull steady','made the canoe sink faster','measured the boat’s outflow','舷外浮架让窄船体在波浪中保持稳定。'),q('Where is an outrigger attached?','outside the canoe’s hull','inside the hull beneath the floorboards','at the canoe’s centre as a mast','它固定在船体外侧。',1,'context'),q('Why is an outrigger useful on choppy water?','it helps prevent the canoe from capsizing','it makes the canoe more narrow','it measures the crew’s output','浮架增强稳定性，帮助防止翻船。',1,'meaning'),q('Which description matches this outrigger?','a projecting support or float on a boat','a small shed behind a house','a tool for drawing an outline','它是船体外伸出的支架或浮体。',1,'meaning')]);
P('outright','Outright combines out and right; as an adjective it means total or complete, and as an adverb it can mean completely, openly, or immediately.',[C('outright.s1','完全的，彻底的','The council imposed an outright ban on fireworks within two blocks of the hospital.','市议会彻底禁止在医院周围两个街区内燃放烟花。','The council imposed an outright ban / on fireworks / within two blocks of the hospital.','outright 作形容词可表示全面、彻底的。','禁令没有留下任何燃放空间。'),C('outright.s2','完全地，直截了当地','When asked whether the map was current, the surveyor denied it outright and showed the revised version.','有人问地图是否最新时，测绘员断然否认，并拿出了修订版。','When asked whether the map was current / the surveyor denied it outright / and showed the revised version.','outright 作副词可表示完全、公开直截了当或立即。','测绘员直接否认并展示了新图。')],M('The council imposed an outright ban on fireworks but allowed shops to sell them freely beside the hospital.','The council imposed an outright ban on fireworks and prohibited their sale and use nearby.','全面禁令与允许附近自由销售烟花相矛盾。','meaning'),[q('What did the council prohibit?','fireworks within two blocks of the hospital','all library outreach','every outdoor concert','市议会全面禁止医院附近燃放烟花。'),q('What did the surveyor do when asked about the map?','denied it directly and showed a revision','outnumbered the council','outgrew the old map','测绘员断然否认地图是最新版本。',2,'context'),q('Which phrase uses outright as an adjective?','an outright ban','denied the claim outright','sold the goods outright','第一项中 outright 修饰名词 ban。',1,'grammar'),q('Which sentence uses outright as an adverb?','She rejected the offer outright.','They imposed an outright ban.','The outright decision was final.','第一句中 outright 修饰 rejected。',2,'grammar')]);
P('outsell','Outsell combines out and sell and means to sell more units or copies than a competing product or seller.',C('outsell.s1','比……更畅销','The new field guide outsold the older edition after birdwatchers praised its clear maps.','观鸟者称赞新野外指南的地图清晰后，它的销量超过了旧版。','The new field guide outsold the older edition / after birdwatchers praised / its clear maps.','outsell 指销售数量超过竞争产品或卖家。','销量较高的新版本胜过旧版。'),M('The new guide outsold the older edition because it sold fewer copies in every shop.','The new guide outsold the older edition because it sold more copies overall.','outsell 表示卖得更多，不能用销量更少来解释。','meaning'),[q('Which book outsold the other?','the new field guide','the older edition','the orthography handbook','销量更高的是新版野外指南。'),q('What did birdwatchers praise?','the new guide’s clear maps','the older edition’s outbuilding','the shop’s electrical outlet','观鸟者称赞新指南的清晰地图。',1,'context'),q('What does outsell mean?','sell more units than a rival','spend more money than a rival','live longer than a rival','outsell 指销售数量超过对手。',1,'meaning'),q('Which product outsells another?','a book with more copies sold than its competing title','a book with fewer copies sold','a book withdrawn before publication','卖出更多册的书销量超过竞争书籍。',1,'context')]);
P('outset','Outset combines out and set and means the moment something begins or its early stage.',[C('outset.s1','开始；开端','At the outset of the expedition, the guide checked every radio and confirmed the route.','探险一开始，向导就检查了每台无线电并确认路线。','At the outset of the expedition / the guide checked every radio / and confirmed the route.','outset 可指某项活动开始的时刻。','检查发生在探险启动之初。'),C('outset.s2','起初阶段','The project faced funding problems at the outset, but later donations allowed the team to finish the survey.','项目初期遇到经费问题，但后来收到的捐款让团队完成了调查。','The project faced funding problems at the outset / but later donations / allowed the team to finish the survey.','at the outset 也可指某过程的早期阶段，与后来的发展相对。','困难发生在项目早期，之后情况改善。')],M('At the outset of the expedition, the guide checked the radios after the team had already returned home.','At the outset of the expedition, the guide checked the radios before the team set out.','outset 指事情开始时，不能把检查安排在探险结束归家之后。','meaning'),[q('What did the guide check at the outset?','every radio','the project’s final donation total','the new book’s sales','探险开始时向导检查了无线电。'),q('What problem did the project face early on?','funding difficulties','an outburst of laughter','an outrigger failure','项目初期遇到经费问题。',2,'context'),q('Which phrase means “at the beginning”?','at the outset','at the outflow','at the outpost','at the outset 表示一开始。',1,'meaning'),q('What happened after the early funding problems?','donations helped the team finish the survey','the expedition had not yet begun','the guide refused to check the radios','后来捐款帮助团队完成调查。',2,'context')]);
})();
